import type { Anchor } from '../stores/anchors'
import type { AnchorReachabilityResult } from './useAnchorReachability'
import type { ModuleRuntime, WalkableMap } from '../types/modules'
import { useModulesStore } from '../stores/modules'
import { buildCandidateModulePairs, expandBoxXZ, type CandidatePair } from './useCandidatePairs'
import { buildLocalWalkableMap } from './useLocalRasterize'
import { prepareEdgePassability } from './useSegmentWalkable'
import { testAnchorPairReachable } from './useAnchorPairAStar'

/**
 * ============================================================
 * 方案 D 主驱动：候选剪枝 + 局部 A* 推导 anchor / module 邻接
 * ============================================================
 *
 * 流程：
 *   1) 收集 anchors，按 moduleName 分组
 *   2) buildCandidateModulePairs(modules, padding) → K 个候选对
 *   3) 对每个候选对：
 *      a) 取 union(boxA, boxB) 并膨胀 padding → 局部矩形
 *      b) buildLocalWalkableMap → 局部 walkableMap（scopedModules = {A, B}）
 *      c) prepareEdgePassability(localMap, true) → 段落 passEdge 表
 *      d) anchors(A) × anchors(B) 笛卡尔积 → 任一对 A* 命中即标记 A↔B reachable
 *   4) 聚合 reachableAnchorPairs / moduleTopology，与全图方案输出格式 100% 兼容
 *
 * 与全图方案（useAnchorReachability）对比：
 *   - 输出字段一致 → AnchorPanel UI 与 overlay 无需修改
 *   - anchorPaths 暂未实现（recordPaths 参数被忽略并打印 warn）
 *
 * 性能特征：
 *   - 候选对越稀疏（地图大、module 散）收益越大
 *   - 候选对密集时（紧凑小地图）退化为多次小 A*，仍快于全图栅格化但优势缩小
 * ============================================================
 */

export interface LocalReachabilityOptions {
  /** XZ 接触阈值（米）。默认 max(2.0, cellSize*4)。 */
  padding?: number
  /** 局部栅格化矩形再膨胀量（米），避免 A* 在 anchor 边界被截断。默认 = padding */
  rasterizePad?: number
  /** 是否开启段落 passEdge 检测（与全图一致）。默认 true。 */
  useSegmentCheck?: boolean
  /** 单对 A* 最大 pop 次数；默认 walkableUtils 内默认值 */
  perPairMaxIter?: number
  /** 记录代表路径（当前未实现）。默认 false。 */
  recordPaths?: boolean
  /** 进度回调：当前已处理候选对数 / 候选对总数 */
  onProgress?: (done: number, total: number) => void
}

interface LocalPairDebug {
  modA: string
  modB: string
  gridW: number
  gridH: number
  walkable: number
  raycastMs: number
  segMs: number
  aStarMs: number
  anchorCombos: number
  reachable: boolean
}

export interface LocalAnchorReachabilityResult extends AnchorReachabilityResult {
  /** 方案 D 专属调试信息 */
  localStats: {
    candidatePairs: number
    totalPairsPossible: number
    skippedByCandidate: number
    rasterizeTotalMs: number
    segmentTotalMs: number
    aStarTotalMs: number
    cellsRasterized: number
    perPair?: LocalPairDebug[]
  }
}

/**
 * 局部 A* 推导 anchor 可达 + module 邻接。
 *
 * @param anchors 全部 anchors（不要求顺序，但输出 reachableAnchorPairs 的索引即此数组下标）
 * @param modules 已加载 module 列表（来自 modulesStore.modules）
 */
export async function computeAnchorReachabilityLocal(
  anchors: Anchor[],
  modules: ModuleRuntime[],
  options: LocalReachabilityOptions = {}
): Promise<LocalAnchorReachabilityResult | null> {
  const t0 = performance.now()

  if (anchors.length === 0) {
    console.warn('[AnchorLocal] 无 anchor 输入')
    return null
  }
  if (options.recordPaths) {
    console.warn('[AnchorLocal] 方案 D 暂未实现 anchorPaths，已忽略 recordPaths=true')
  }

  // ---- 1. 决定全局 cellSize（与全图栅格化口径一致：max(sizeX, sizeZ) / resolution）----
  const modulesStore = useModulesStore()
  const merged = modulesStore.mergedCollisionBox
  if (!merged || merged.isEmpty()) {
    console.error('[AnchorLocal] 无 mergedCollisionBox，无法决定 cellSize')
    return null
  }
  const sizeX = merged.max.x - merged.min.x
  const sizeZ = merged.max.z - merged.min.z
  const cellSize = Math.max(sizeX, sizeZ) / modulesStore.gridResolution
  const slopeThresholdDeg = modulesStore.slopeThresholdDeg
  const padding = options.padding ?? Math.max(2.0, cellSize * 4)
  const rasterizePad = options.rasterizePad ?? padding
  const useSegment = options.useSegmentCheck ?? true

  // ---- 2. 按 moduleName 分组 anchors，并记录原数组索引 ----
  const anchorIdxByModule = new Map<string, number[]>() // moduleName → 数组下标列表
  for (let i = 0; i < anchors.length; i++) {
    const name = anchors[i].moduleName
    const list = anchorIdxByModule.get(name) ?? []
    list.push(i)
    anchorIdxByModule.set(name, list)
  }

  // ---- 3. 候选对生成 ----
  const candRes = buildCandidateModulePairs(modules, padding)
  console.log(
    `[AnchorLocal] 候选对: ${candRes.stats.candidateCount}/${candRes.stats.totalPossible} ` +
      `(modules=${candRes.stats.moduleCount}, padding=${padding.toFixed(2)}m, ` +
      `pairBuildMs=${candRes.stats.elapsedMs.toFixed(1)})`
  )

  // 仅保留两端都有 anchor 的候选对（无 anchor 的 module 不可能产生可达对）
  const validPairs: CandidatePair[] = candRes.pairs.filter(
    (p) =>
      (anchorIdxByModule.get(p.modA.name)?.length ?? 0) > 0 &&
      (anchorIdxByModule.get(p.modB.name)?.length ?? 0) > 0
  )
  const skippedByAnchor = candRes.pairs.length - validPairs.length
  if (skippedByAnchor > 0) {
    console.log(`[AnchorLocal] 跳过 ${skippedByAnchor} 个候选对：至少一端无 anchor`)
  }

  // ---- 4. 遍历候选对，局部栅格化 + 局部段落检测 + anchor pair A* ----
  const reachPairsSet = new Set<string>()
  const reachPairs: Array<[number, number]> = []
  const perPairDebug: LocalPairDebug[] = []
  let rasterizeTotalMs = 0
  let segmentTotalMs = 0
  let aStarTotalMs = 0
  let cellsRasterized = 0

  function addPair(a: number, b: number) {
    if (a === b) return
    const lo = a < b ? a : b
    const hi = a < b ? b : a
    const key = `${lo}-${hi}`
    if (reachPairsSet.has(key)) return
    reachPairsSet.add(key)
    reachPairs.push([lo, hi])
  }

  for (let pi = 0; pi < validPairs.length; pi++) {
    const pair = validPairs[pi]
    const aIdxList = anchorIdxByModule.get(pair.modA.name)!
    const bIdxList = anchorIdxByModule.get(pair.modB.name)!
    const pairTopT0 = performance.now()
    console.log(
      `[AnchorLocal] >>> candidate ${pi + 1}/${validPairs.length}: ` +
        `${pair.modA.name}(${aIdxList.length}) × ${pair.modB.name}(${bIdxList.length}) = ` +
        `${aIdxList.length * bIdxList.length} combos`
    )

    // 4a) 局部栅格化范围 = union(box) + rasterizePad
    const localBox = expandBoxXZ(pair.unionBoxXZ, rasterizePad)
    const rasterRes = buildLocalWalkableMap({
      boxXZ: localBox,
      cellSize,
      slopeThresholdDeg,
      scopedModules: [pair.modA, pair.modB]
    })
    if (!rasterRes) {
      console.warn('[AnchorLocal] 局部栅格化失败，跳过', pair.modA.name, pair.modB.name)
      continue
    }
    rasterizeTotalMs += rasterRes.stats.raycastMs
    cellsRasterized += rasterRes.stats.totalCells
    const localMap: WalkableMap = rasterRes.map

    // 4b) 局部段落检测（与全图同源；force=true 强制刷新局部表）
    let segMs = 0
    if (useSegment) {
      const segT0 = performance.now()
      await prepareEdgePassability(localMap, true, {
        // 局部规模一般 << 10k cells，直接一次性处理
        batchEdgesPerFrame: 100_000
      })
      segMs = performance.now() - segT0
      segmentTotalMs += segMs
    }

    // 4c) anchor 对笛卡尔积 → 任一可达即标记
    //     每对都单独计时并打印，便于在 console 实时定位是哪对 A* 卡住
    let reachableFlag = false
    let combos = 0
    const aStarT0 = performance.now()
    outer: for (const ai of aIdxList) {
      for (const bi of bIdxList) {
        combos++
        const A = anchors[ai]
        const B = anchors[bi]
        const pairT0 = performance.now()
        const r = testAnchorPairReachable(A.worldX, A.worldZ, B.worldX, B.worldZ, localMap, {
          maxIterations: options.perPairMaxIter
        })
        const pairMs = performance.now() - pairT0
        // 慢对（>50ms）用 warn 高亮，便于在 DevTools 过滤
        const log = pairMs > 50 ? console.warn : console.log
        log(
          `[AnchorLocal] pair ${pi + 1}/${validPairs.length} | ` +
            `${pair.modA.name}#${ai}(${A.id}) ↔ ${pair.modB.name}#${bi}(${B.id}) | ` +
            `${pairMs.toFixed(1)}ms | iter=${r.iterations} | reachable=${r.reachable}`
        )
        if (r.reachable) {
          addPair(ai, bi)
          reachableFlag = true
          break outer
        }
      }
    }
    const aMs = performance.now() - aStarT0
    aStarTotalMs += aMs

    perPairDebug.push({
      modA: pair.modA.name,
      modB: pair.modB.name,
      gridW: rasterRes.stats.width,
      gridH: rasterRes.stats.height,
      walkable: rasterRes.stats.walkableCells,
      raycastMs: rasterRes.stats.raycastMs,
      segMs,
      aStarMs: aMs,
      anchorCombos: combos,
      reachable: reachableFlag
    })

    if (options.onProgress) options.onProgress(pi + 1, validPairs.length)
    const pairTopMs = performance.now() - pairTopT0
    console.log(
      `[AnchorLocal] <<< candidate ${pi + 1}/${validPairs.length} done in ${pairTopMs.toFixed(1)}ms ` +
        `(raster=${rasterRes.stats.raycastMs.toFixed(0)}, seg=${segMs.toFixed(0)}, ` +
        `aStar=${aMs.toFixed(0)}, combos=${combos}, reachable=${reachableFlag})`
    )
    // 主线程让步：每对让一次，确保 console 实时刷出 + UI 不卡死
    await new Promise((r) => setTimeout(r, 0))
  }

  // ---- 5. 聚合 module 邻接 ----
  const moduleEdgeSet = new Set<string>()
  const moduleTopology: Array<[string, string]> = []
  for (const [i, j] of reachPairs) {
    const a = anchors[i].moduleName
    const b = anchors[j].moduleName
    if (a === b) continue
    const lo = a < b ? a : b
    const hi = a < b ? b : a
    const key = `${lo}||${hi}`
    if (moduleEdgeSet.has(key)) continue
    moduleEdgeSet.add(key)
    moduleTopology.push([lo, hi])
  }

  const elapsedMs = performance.now() - t0
  console.log(
    `[AnchorLocal] 完成: anchors=${anchors.length}, candidatePairs=${validPairs.length}, ` +
      `reachablePairs=${reachPairs.length}, moduleEdges=${moduleTopology.length}, ` +
      `elapsed=${elapsedMs.toFixed(1)}ms (rasterize=${rasterizeTotalMs.toFixed(0)}, ` +
      `seg=${segmentTotalMs.toFixed(0)}, aStar=${aStarTotalMs.toFixed(0)})`
  )

  return {
    anchors: anchors.slice(),
    reachableAnchorPairs: reachPairs,
    pairKeySet: reachPairsSet,
    moduleTopology,
    anchorPaths: undefined,
    stats: {
      totalIterations: 0, // 不再有"全图扩散迭代"
      elapsedMs,
      exploredCells: cellsRasterized,
      reachablePairCount: reachPairs.length,
      moduleEdgeCount: moduleTopology.length
    },
    localStats: {
      candidatePairs: validPairs.length,
      totalPairsPossible: candRes.stats.totalPossible,
      skippedByCandidate: candRes.stats.totalPossible - validPairs.length,
      rasterizeTotalMs,
      segmentTotalMs,
      aStarTotalMs,
      cellsRasterized,
      perPair: perPairDebug
    }
  }
}
