import { defineStore } from 'pinia'
import { computed, ref, shallowRef, watch } from 'vue'
import { useModulesStore } from './modules'
import type { AnchorReachabilityResult } from '../composables/useAnchorReachability'

/**
 * ============================================================
 * Anchor（可达点）store
 * ============================================================
 *
 * 每个 module 可挂多个 anchor（worldX/Z + 吸附后的 cell 下标）。
 * 用户可：
 *   - 一键"生成默认 anchors"（取 worldBox 中心吸附）
 *   - 在 AnchorPanel 行内增删
 *   - 在 minimap 添加模式下点击 walkable 区域新增（落点 moduleId 强制匹配）
 *
 * 一次性多源 A* 跑出"anchor 两两是否可达"，再按 module 聚合得到 module
 * 邻接图（替代 useAStarReachability 中的 Voronoi buildModuleTopology）。
 *
 * 设计要点：
 *   - 内存态，不持久化（用户已选 q3=C）；切换 manifest / walkableMap 会自动清空
 *   - shallowRef 包装 result，避免大 typed-array 被深度响应
 *   - 监听 walkableMap 变化自动 clearResult
 * ============================================================
 */

export interface Anchor {
  /** 唯一 id（`${moduleName}#${seq}`） */
  id: string
  moduleName: string
  worldX: number
  worldZ: number
  /** 吸附到 walkableMap 后的 cell 线性下标（j*width+i） */
  cellIdx: number
  /** true=自动生成默认 anchor；false=用户手动添加 */
  isDefault: boolean
}

export const useAnchorStore = defineStore('anchors', () => {
  const modulesStore = useModulesStore()

  /** 主存储：按 moduleName 分组。Map 不是天然响应，所以包一层 ref 计数触发更新 */
  const byModule = ref<Map<string, Anchor[]>>(new Map())
  /** Map 内部变更后自增以触发 watch */
  const revision = ref<number>(0)

  /** 选中的 anchor id（用于高亮 + 删除） */
  const selectedAnchorId = ref<string | null>(null)

  /**
   * 添加 anchor 模式：非 null 时表示用户正在为该 module 选点
   * minimap 下一次点击 walkable 处即 addAnchor(addModeModuleName, x, z)
   */
  const addModeModuleName = ref<string | null>(null)

  /** 计算结果 */
  const result = shallowRef<AnchorReachabilityResult | null>(null)

  /** 计算中 */
  const isComputing = ref<boolean>(false)

  /** 是否记录路径（默认 false，开启会占内存） */
  const recordPaths = ref<boolean>(false)

  /** hover 高亮 */
  const hoveredAnchorId = ref<string | null>(null)

  /** overlay 重绘脏标记 */
  const overlayDirty = ref<number>(0)

  /**
   * 是否启用"段落悬崖检测"（A→B 之间向下射线，精确识别高墙/深沟/夹层）。
   * 默认 true。关闭后退回仅 heightMap |Δy|≤1.5m 阈值（可能误判跨沟）。
   *
   * 启用后首次"全图扩散"前会触发预计算 passRight/passDown
   * （可能耗时数秒至数十秒），之后所有计算复用查表。
   */
  const useSegmentCheck = ref<boolean>(true)

  /** 段落检测预计算进度（0~1）。0 表示未开始或已完成 */
  const segmentPrepareProgress = ref<number>(0)
  const isSegmentPreparing = ref<boolean>(false)

  // ============ computed ============
  const totalAnchorCount = computed(() => {
    // revision 触发响应
    void revision.value
    let n = 0
    for (const arr of byModule.value.values()) n += arr.length
    return n
  })

  const allAnchors = computed<Anchor[]>(() => {
    void revision.value
    const out: Anchor[] = []
    for (const arr of byModule.value.values()) out.push(...arr)
    return out
  })

  const moduleNamesWithAnchors = computed<string[]>(() => {
    void revision.value
    return [...byModule.value.keys()]
  })

  const hasResult = computed(() => result.value !== null)

  // ============ actions ============
  function getByModule(moduleName: string): Anchor[] {
    void revision.value
    return byModule.value.get(moduleName) ?? []
  }

  function getById(id: string): Anchor | null {
    void revision.value
    for (const arr of byModule.value.values()) {
      for (const a of arr) if (a.id === id) return a
    }
    return null
  }

  function nextSeq(moduleName: string): number {
    const arr = byModule.value.get(moduleName)
    if (!arr || arr.length === 0) return 1
    let max = 0
    for (const a of arr) {
      const m = /#(\d+)$/.exec(a.id)
      if (m) max = Math.max(max, Number(m[1]))
    }
    return max + 1
  }

  /** 替换全部（默认 anchor 生成用） */
  function setAll(map: Map<string, Anchor[]>) {
    byModule.value = map
    revision.value++
    clearResult()
    invalidateOverlay()
  }

  /** 直接增一个 anchor（调用方负责吸附与 cellIdx 计算） */
  function pushAnchor(anchor: Anchor) {
    const arr = byModule.value.get(anchor.moduleName) ?? []
    arr.push(anchor)
    byModule.value.set(anchor.moduleName, arr)
    revision.value++
    clearResult()
    invalidateOverlay()
  }

  function removeAnchor(anchorId: string) {
    for (const [name, arr] of byModule.value) {
      const idx = arr.findIndex((a) => a.id === anchorId)
      if (idx >= 0) {
        arr.splice(idx, 1)
        if (arr.length === 0) byModule.value.delete(name)
        else byModule.value.set(name, arr)
        if (selectedAnchorId.value === anchorId) selectedAnchorId.value = null
        revision.value++
        clearResult()
        invalidateOverlay()
        return
      }
    }
  }

  /**
   * 原地更新某 anchor 的世界坐标（拖拽移动场景）。
   * - 调用方负责提供已吸附后的 worldX/worldZ/cellIdx
   * - moduleName 保持不变（一个 anchor 始终归属其原 module；拖出 module 边界由调用方决定是否报警告）
   * - 标记 isDefault=false（手动调整过的不再视为"默认生成"）
   * - 会清空旧的可达计算结果（坐标变了，邻接需要重算）
   * - performant：避免不必要的重 hover/selected 状态变更
   */
  function updateAnchorPosition(
    id: string,
    worldX: number,
    worldZ: number,
    cellIdx: number
  ): boolean {
    for (const arr of byModule.value.values()) {
      const a = arr.find((x) => x.id === id)
      if (a) {
        a.worldX = worldX
        a.worldZ = worldZ
        a.cellIdx = cellIdx
        a.isDefault = false
        revision.value++
        clearResult()
        invalidateOverlay()
        return true
      }
    }
    return false
  }

  function clearAll() {
    byModule.value = new Map()
    selectedAnchorId.value = null
    addModeModuleName.value = null
    revision.value++
    clearResult()
    invalidateOverlay()
  }

  function selectAnchor(id: string | null) {
    selectedAnchorId.value = id
    invalidateOverlay()
  }

  function enterAddMode(moduleName: string) {
    addModeModuleName.value = moduleName
    invalidateOverlay()
  }

  function leaveAddMode() {
    addModeModuleName.value = null
    invalidateOverlay()
  }

  function setHovered(id: string | null) {
    hoveredAnchorId.value = id
    invalidateOverlay()
  }

  function setResult(r: AnchorReachabilityResult | null) {
    result.value = r
    invalidateOverlay()
  }

  function clearResult() {
    if (result.value !== null) {
      result.value = null
      invalidateOverlay()
    }
  }

  function setComputing(v: boolean) {
    isComputing.value = v
  }

  function setRecordPaths(v: boolean) {
    recordPaths.value = v
  }

  function setUseSegmentCheck(v: boolean) {
    useSegmentCheck.value = v
  }

  function setSegmentPrepareProgress(p: number) {
    segmentPrepareProgress.value = p
  }

  function setSegmentPreparing(v: boolean) {
    isSegmentPreparing.value = v
  }

  function invalidateOverlay() {
    overlayDirty.value++
  }

  // ============ 自动失效：walkableMap / manifest 变化时清空结果 ============
  watch(
    () => modulesStore.walkableMap,
    () => {
      // walkable 变了，旧的 cellIdx 全部失效；为简单起见整体清空
      clearAll()
    }
  )
  watch(
    () => modulesStore.manifest,
    () => {
      clearAll()
    }
  )

  return {
    // state
    byModule,
    revision,
    selectedAnchorId,
    addModeModuleName,
    result,
    isComputing,
    recordPaths,
    hoveredAnchorId,
    overlayDirty,
    useSegmentCheck,
    segmentPrepareProgress,
    isSegmentPreparing,
    // computed
    totalAnchorCount,
    allAnchors,
    moduleNamesWithAnchors,
    hasResult,
    // actions
    getByModule,
    getById,
    nextSeq,
    setAll,
    pushAnchor,
    removeAnchor,
    updateAnchorPosition,
    clearAll,
    selectAnchor,
    enterAddMode,
    leaveAddMode,
    setHovered,
    setResult,
    clearResult,
    setComputing,
    setRecordPaths,
    setUseSegmentCheck,
    setSegmentPrepareProgress,
    setSegmentPreparing,
    invalidateOverlay
  }
})
