import { useModulesStore } from '../stores/modules'
import { useAnchorStore } from '../stores/anchors'

/**
 * ============================================================
 * Anchor 推导方案的导出 —— 与 BFS / A* 导出并列的第三套
 * ============================================================
 *
 * 与 useAStarReachabilityExport / useReachabilityExport 的区别：
 *   - 数据源是 anchorStore.result.moduleTopology（anchor 两两可达聚合到 module）
 *   - 不存在"root / 父子树 / depth"概念（anchor 推导是无向连通图）
 *   - 不变原则：reachableNeighbors 来自 anchor 寻路结果，无关 anchor 数量也无关 anchor id，
 *     仅保留 module-级邻接信息（A↔B 双向写入两个 module 的 reachableNeighbors）
 *
 * 字段语义：
 *   reachableNeighbors[m] = { n | (m,n) ∈ moduleTopology } 字典序、去重、不含自身
 *   - 若 module m 无任何可达对手（或 m 上根本没 anchor） → []
 *   - 与 A* 版同名字段语义一致，下游可统一消费
 * ============================================================
 */

/** 计算每个 module 的可达邻居（按 moduleName → string[]，字典序、去重、不含自身） */
function computeAnchorNeighborsMap(): Map<string, string[]> {
  const out = new Map<string, string[]>()
  const anchorStore = useAnchorStore()
  const r = anchorStore.result
  if (!r) return out

  const setMap = new Map<string, Set<string>>()
  for (const [a, b] of r.moduleTopology) {
    if (a === b) continue
    if (!setMap.has(a)) setMap.set(a, new Set())
    if (!setMap.has(b)) setMap.set(b, new Set())
    setMap.get(a)!.add(b)
    setMap.get(b)!.add(a)
  }
  for (const [name, set] of setMap) {
    out.set(name, Array.from(set).sort())
  }
  return out
}

/**
 * 在原 manifest 基础上克隆并为每个 module 附加 `reachableNeighbors` 字段（Anchor 版本）。
 * - 顶层结构与字段保持原样
 * - 每个 module 的原字段保持不变；末尾追加 `reachableNeighbors: string[]`
 * - 数据源：anchorStore.result.moduleTopology
 *
 * 抛出：若 store 中没有 manifest，抛 Error。
 */
export function buildAnchorAnnotatedManifest(): Record<string, unknown> {
  const modulesStore = useModulesStore()
  const manifest = modulesStore.manifest
  if (!manifest) {
    throw new Error('当前没有已加载的 manifest，无法导出')
  }
  const neighborsMap = computeAnchorNeighborsMap()

  const modulesOut = manifest.modules.map((m) => {
    const cloned: Record<string, unknown> = {
      name: m.name,
      transform: {
        position: [...m.transform.position] as [number, number, number],
        rotation: [...m.transform.rotation] as [number, number, number, number],
        scale: [...m.transform.scale] as [number, number, number]
      },
      bounds: { x: m.bounds.x, y: m.bounds.y, z: m.bounds.z },
      collision_name: [...m.collision_name],
      ply_name: [...m.ply_name],
      reachableNeighbors: neighborsMap.get(m.name) ?? []
    }
    return cloned
  })

  return {
    baseUrl: manifest.baseUrl,
    morton: manifest.morton,
    fileType: manifest.fileType,
    modules: modulesOut
  }
}

/**
 * 触发浏览器下载：带 reachableNeighbors 字段（Anchor 版本）的新 manifest JSON。
 * @param filename 缺省为 modules-with-anchor-reachability-<timestamp>.json
 */
export function downloadAnchorAnnotatedManifestJson(filename?: string): Record<string, unknown> {
  const data = buildAnchorAnnotatedManifest()
  const json = JSON.stringify(data, null, 2)
  triggerDownload(json, filename ?? `modules-with-anchor-reachability-${tsLabel()}.json`)
  return data
}

/* ---------- 内部工具 ---------- */

function tsLabel(): string {
  return new Date().toISOString().replace(/[:.]/g, '-').replace('T', '_').slice(0, 19)
}

function triggerDownload(text: string, filename: string) {
  const blob = new Blob([text], { type: 'application/json' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = filename
  document.body.appendChild(a)
  a.click()
  document.body.removeChild(a)
  setTimeout(() => URL.revokeObjectURL(url), 1000)
}
