import { Mesh, Object3D, Raycaster, Vector3 } from 'three'
import type { WalkableMap } from '../types/modules'
import type { ModuleRuntime } from '../types/modules'
import { useTerrainStore } from '../stores/terrain'
import type { BoxXZ } from './useCandidatePairs'

/**
 * ============================================================
 * 局部栅格化（方案 D 的核心）
 * ============================================================
 *
 * 与 useRasterizer 的区别：
 *   1) 栅格范围 = 入参 BoxXZ（不是全图 mergedCollisionBox）
 *   2) 同步执行（局部格数 < 10k 时通常 <50ms，不需要分帧）
 *   3) 不写入 modulesStore.walkableMap（返回局部 map，归调用方所有）
 *   4) cellSize 由调用方传入（一般沿用全图 cellSize 以保持一致性）
 *
 * 复用：所有"地面定义、坡度过滤、moduleIdMap 反查"语义与 useRasterizer 完全一致。
 *
 * 关键设计：cellSize 从外部传入而非自适应
 *   - 自适应 cellSize（按 box 大小 / resolution）会导致同一物理位置在不同
 *     pair 的局部 map 上有不同的"格子分辨率"，passEdge 阈值难以统一；
 *   - 用全图 cellSize（modulesStore.gridResolution 推导）作为基准，所有
 *     局部 map 物理网格密度一致，A* 结果可比、与全图方案口径一致。
 * ============================================================
 */

const SKY_OFFSET = 200
const RAY_FAR_PADDING = 200

export interface LocalRasterizeOptions {
  /** 栅格化区域（XZ 投影矩形，世界坐标） */
  boxXZ: BoxXZ
  /** 单元格世界尺寸（米）；建议沿用全图 cellSize */
  cellSize: number
  /** 坡度阈值（度），与全图栅格化一致 */
  slopeThresholdDeg: number
  /** 仅这些 module 的 worldBox 参与 moduleIdMap 反查（默认所有 loaded module） */
  scopedModules?: ModuleRuntime[]
}

export interface LocalRasterizeResult {
  map: WalkableMap
  stats: {
    width: number
    height: number
    totalCells: number
    walkableCells: number
    raycastMs: number
    raycastCount: number
  }
}

/**
 * 在指定 BoxXZ 内做顶视 raycast 栅格化，返回局部 WalkableMap。
 *
 * 性能：raycast 一次取所有 hits（与 useRasterizer 一致，不开 firstHitOnly），
 * 用于穿过屋顶找下层地面。
 */
export function buildLocalWalkableMap(opts: LocalRasterizeOptions): LocalRasterizeResult | null {
  const t0 = performance.now()
  const terrainStore = useTerrainStore()

  // 收集地形 mesh
  const meshes: Mesh[] = []
  const terrainRoots: Object3D[] = terrainStore.terrains.map((t) => t.object3D)
  for (const root of terrainRoots) {
    root.updateMatrixWorld(true)
    root.traverse((obj) => {
      const m = obj as Mesh
      if (m.isMesh && m.geometry) meshes.push(m)
    })
  }
  if (meshes.length === 0) {
    console.error('[LocalRasterizer] 主预览区没有地形 mesh')
    return null
  }

  const { boxXZ, cellSize, slopeThresholdDeg } = opts
  const sizeX = boxXZ.maxX - boxXZ.minX
  const sizeZ = boxXZ.maxZ - boxXZ.minZ
  if (sizeX <= 0 || sizeZ <= 0 || cellSize <= 0) {
    console.error('[LocalRasterizer] 非法 box 或 cellSize', { boxXZ, cellSize })
    return null
  }

  const width = Math.max(1, Math.ceil(sizeX / cellSize))
  const height = Math.max(1, Math.ceil(sizeZ / cellSize))
  const total = width * height
  const slopeCos = Math.cos((slopeThresholdDeg * Math.PI) / 180)

  // 模块 box 反查列表
  const moduleBoxes = (opts.scopedModules ?? []).filter((m) => !m.worldBox.isEmpty()).map((m) => ({
    box: m.worldBox,
    idPlus1: m.index + 1
  }))
  const lookupTolerance = cellSize

  function findModuleId(x: number, z: number): number {
    for (const mb of moduleBoxes) {
      if (x >= mb.box.min.x && x <= mb.box.max.x && z >= mb.box.min.z && z <= mb.box.max.z) {
        return mb.idPlus1
      }
    }
    let bestId = 0
    let bestDist = lookupTolerance
    for (const mb of moduleBoxes) {
      const dx = x < mb.box.min.x ? mb.box.min.x - x : x > mb.box.max.x ? x - mb.box.max.x : 0
      const dz = z < mb.box.min.z ? mb.box.min.z - z : z > mb.box.max.z ? z - mb.box.max.z : 0
      if (dx > 0 && dz > 0) continue
      const d = dx + dz
      if (d <= bestDist) {
        bestDist = d
        bestId = mb.idPlus1
      }
    }
    return bestId
  }

  // y 范围：取 scopedModules 的 y 联合，缺省回退到地形整体
  let yMin = Infinity
  let yMax = -Infinity
  for (const mb of moduleBoxes) {
    if (mb.box.min.y < yMin) yMin = mb.box.min.y
    if (mb.box.max.y > yMax) yMax = mb.box.max.y
  }
  if (!Number.isFinite(yMin) || !Number.isFinite(yMax)) {
    const tb = terrainStore.mergedBox
    if (tb && !tb.isEmpty()) {
      yMin = tb.min.y
      yMax = tb.max.y
    } else {
      yMin = -1000
      yMax = 1000
    }
  }

  const walkable = new Uint8Array(total)
  const moduleIdMap = new Uint16Array(total)
  const heightMap = new Float32Array(total)
  heightMap.fill(NaN)

  const raycaster = new Raycaster()
  raycaster.ray.direction.set(0, -1, 0)
  raycaster.far = yMax - yMin + SKY_OFFSET + RAY_FAR_PADDING
  const skyY = yMax + SKY_OFFSET
  const origin = new Vector3()
  const normalWorld = new Vector3()

  let raycastCount = 0
  let walkableCount = 0

  for (let j = 0; j < height; j++) {
    for (let i = 0; i < width; i++) {
      const idx = j * width + i
      const wx = boxXZ.minX + (i + 0.5) * cellSize
      const wz = boxXZ.minZ + (j + 0.5) * cellSize
      origin.set(wx, skyY, wz)
      raycaster.ray.origin.copy(origin)
      const hits = raycaster.intersectObjects(meshes, false)
      raycastCount++
      if (hits.length === 0) {
        moduleIdMap[idx] = findModuleId(wx, wz)
        continue
      }
      let groundIdx = -1
      for (let hi = 0; hi < hits.length; hi++) {
        const h = hits[hi]
        if (!h.face) {
          groundIdx = hi
          break
        }
        normalWorld.copy(h.face.normal).transformDirection(h.object.matrixWorld).normalize()
        if (normalWorld.y >= slopeCos) {
          groundIdx = hi
          break
        }
      }
      if (groundIdx >= 0) {
        walkable[idx] = 1
        walkableCount++
        const hp = hits[groundIdx].point
        moduleIdMap[idx] = findModuleId(hp.x, hp.z)
        heightMap[idx] = hp.y
      } else {
        const hp = hits[0].point
        moduleIdMap[idx] = findModuleId(hp.x, hp.z)
      }
    }
  }

  const raycastMs = performance.now() - t0
  const map: WalkableMap = {
    width,
    height,
    originX: boxXZ.minX,
    originZ: boxXZ.minZ,
    cellSize,
    walkable,
    moduleIdMap,
    heightMap
  }
  return {
    map,
    stats: {
      width,
      height,
      totalCells: total,
      walkableCells: walkableCount,
      raycastMs,
      raycastCount
    }
  }
}
