import type { WalkableMap } from '../types/modules'

/**
 * ============================================================
 * walkable map 通用工具
 * ============================================================
 *
 * 抽出自 useAStarReachability.ts，供 anchor 方案与未来其它扩散
 * 算法共用，确保多个算法在"边可走判定"、"螺旋吸附"、"cell↔世界
 * 坐标换算"上行为完全一致。
 *
 * **关键不变量**：所有基于 walkableMap 的 4 邻接扩散必须使用
 * `makePassEdge(map)` 返回的 passEdge 函数，禁止各自重复实现。
 * ============================================================
 */

/** clamp 到 [min, max] */
export function clamp(v: number, min: number, max: number): number {
  return v < min ? min : v > max ? max : v
}

/**
 * 螺旋查找最近的 walkable cell（与 useAStarReachability 完全一致的实现）。
 * 返回找到的 (i, j)；若 maxR 内无 walkable，返回 null。
 *
 * 性能：典型 maxR=64 下 < 0.5ms，整张地图未命中需要 O(maxR^2) 次访问。
 */
export function spiralFindWalkable(
  walkable: Uint8Array,
  width: number,
  height: number,
  i0: number,
  j0: number,
  maxR: number
): { i: number; j: number } | null {
  for (let r = 1; r <= maxR; r++) {
    for (let i = -r; i <= r; i++) {
      const x = i0 + i
      if (x < 0 || x >= width) continue
      const yTop = j0 - r
      const yBot = j0 + r
      if (yTop >= 0 && walkable[yTop * width + x] === 1) return { i: x, j: yTop }
      if (yBot < height && walkable[yBot * width + x] === 1) return { i: x, j: yBot }
    }
    for (let j = -r + 1; j <= r - 1; j++) {
      const y = j0 + j
      if (y < 0 || y >= height) continue
      const xLeft = i0 - r
      const xRight = i0 + r
      if (xLeft >= 0 && walkable[y * width + xLeft] === 1) return { i: xLeft, j: y }
      if (xRight < width && walkable[y * width + xRight] === 1) return { i: xRight, j: y }
    }
  }
  return null
}

/**
 * 默认螺旋吸附半径：与 useAStarReachability 内的起点吸附口径一致：
 *   max(8, floor(max(width, height) / 16))
 */
export function defaultSnapRadius(width: number, height: number): number {
  return Math.max(8, Math.floor(Math.max(width, height) / 16))
}

/** cell 线性下标 → 世界 (x, z)（cell 中心） */
export function cellIdxToWorld(map: WalkableMap, idx: number): { x: number; z: number } {
  const i = idx % map.width
  const j = (idx - i) / map.width
  return {
    x: map.originX + (i + 0.5) * map.cellSize,
    z: map.originZ + (j + 0.5) * map.cellSize
  }
}

/** 世界 (x, z) → cell (i, j)（clamp 到地图范围内） */
export function worldToCell(map: WalkableMap, worldX: number, worldZ: number): { i: number; j: number } {
  const i = clamp(Math.floor((worldX - map.originX) / map.cellSize), 0, map.width - 1)
  const j = clamp(Math.floor((worldZ - map.originZ) / map.cellSize), 0, map.height - 1)
  return { i, j }
}

/**
 * 4 邻接段落可走判定工厂：
 *   - 优先使用预计算的 passRight/passDown 表（O(1) 查表，与 useAStarReachability 行为完全一致）
 *   - 表不存在时降级到 heightMap |Δy| ≤ maxStepHeight 阈值（旧行为）
 *
 * **重要约定**：fromIdx 与 toIdx 必须是 4 邻接（差为 ±1 或 ±width），
 * 否则一律返回 false。调用方有责任保证邻接关系。
 */
export function makePassEdge(map: WalkableMap, maxStepHeight = 1.5) {
  const passRight = map.passRight ?? null
  const passDown = map.passDown ?? null
  const hasPassTable = passRight !== null && passDown !== null
  const { width, heightMap } = map

  return function passEdge(fromIdx: number, toIdx: number): boolean {
    if (hasPassTable) {
      const d = toIdx - fromIdx
      if (d === 1) return passRight![fromIdx] === 1
      if (d === -1) return passRight![toIdx] === 1
      if (d === width) return passDown![fromIdx] === 1
      if (d === -width) return passDown![toIdx] === 1
      return false
    }
    const yA = heightMap[fromIdx]
    const yB = heightMap[toIdx]
    if (!Number.isFinite(yA) || !Number.isFinite(yB)) return true
    return Math.abs(yA - yB) <= maxStepHeight
  }
}

/**
 * 通用 4 邻接最小优先队列（二叉堆，扁平 typed-array 等价实现）。
 *
 * 抽出自 useAStarReachability.ts —— 与那里的 MinHeap 行为完全一致。
 *
 * 元素 = (priority: number, idx: number)；priority 小者先出。
 * 用扁平 number[] 而非两个数组，避免对象分配，配合 V8 SMI 优化效果最好。
 */
export class MinHeap {
  private heap: number[] = []

  get size(): number {
    return this.heap.length >> 1
  }

  push(f: number, idx: number) {
    this.heap.push(f, idx)
    this.bubbleUp(this.size - 1)
  }

  pop(): { f: number; idx: number } | null {
    if (this.heap.length === 0) return null
    const f = this.heap[0]
    const idx = this.heap[1]
    const lastF = this.heap[this.heap.length - 2]
    const lastIdx = this.heap[this.heap.length - 1]
    this.heap.length -= 2
    if (this.heap.length > 0) {
      this.heap[0] = lastF
      this.heap[1] = lastIdx
      this.sinkDown(0)
    }
    return { f, idx }
  }

  private bubbleUp(node: number) {
    while (node > 0) {
      const parent = (node - 1) >> 1
      if (this.heap[node * 2] < this.heap[parent * 2]) {
        this.swap(node, parent)
        node = parent
      } else {
        break
      }
    }
  }

  private sinkDown(node: number) {
    const n = this.size
    while (true) {
      const l = node * 2 + 1
      const r = node * 2 + 2
      let best = node
      if (l < n && this.heap[l * 2] < this.heap[best * 2]) best = l
      if (r < n && this.heap[r * 2] < this.heap[best * 2]) best = r
      if (best === node) break
      this.swap(node, best)
      node = best
    }
  }

  private swap(a: number, b: number) {
    const af = this.heap[a * 2]
    const ai = this.heap[a * 2 + 1]
    this.heap[a * 2] = this.heap[b * 2]
    this.heap[a * 2 + 1] = this.heap[b * 2 + 1]
    this.heap[b * 2] = af
    this.heap[b * 2 + 1] = ai
  }
}
