import { Mesh, Object3D, Raycaster, Vector3 } from 'three'
import type { WalkableMap } from '../types/modules'
import { useTerrainStore } from '../stores/terrain'

/**
 * 段落悬崖/高墙检测（思想来自 viewer-sdk 的 `physics-world-manager.checkCliffAhead`）。
 *
 * ------------------------------------------------------------------
 * 背景：为什么不能只靠 `walkable + heightMap` 判断 4 邻接 cell 是否可走？
 * ------------------------------------------------------------------
 *
 * 栅格化（`useRasterizer.ts`）对每格只做"自顶向下一束射线 → 取首个法线朝
 * 上、坡度合格的命中"作为该格地面。两个 4 邻接 cell 各自有合法地面（沟两
 * 岸的平台），但中间真实地形是深沟/高墙时：
 *   - 若沟底足够宽，沟正下方的 cell 同样能被栅格化吸到"沟底平台"，
 *     heightMap 是沟底 y，与两岸 y 差大 → 上一轮的 `passHeight` 能拦下；
 *   - 但**死角**很多：
 *     * 沟太窄（一格内）：沟两岸 cell 直接相邻，passHeight 看 |yA - yB|
 *       很小（因为都是同高度的平台），漏判 ✗；
 *     * 沟正下方栅格化时无命中（射线射穿空白）→ heightMap=NaN，
 *       passHeight 容错返回 true，漏判 ✗；
 *     * 两层楼夹层（上层走廊在下层走廊正上方）：两相邻 cell 若各自栅格化
 *       吸到不同楼层，|Δy| 大 passHeight 能拦；若都吸到上层，则下层一段
 *       cell 全是不可走但两端 cell 直接接壤，passHeight 漏判 ✗。
 *
 * 解决：参考 viewer-sdk 的"前瞻三点向下射线"思想，**在 4 邻接的两个 cell
 * 之间**做段落式向下射线检测：
 *
 *      A中点      AB中点      B中点
 *        ●─────────●─────────●        ← 三个采样点
 *        │         │         │
 *        ▼         ▼         ▼        ← 向下射线（起点抬高 0.5m）
 *      hit?      hit?      hit?
 *
 *   判定：
 *     - 任一采样点向下射线**没命中地面** → 视为深渊，不可走；
 *     - 命中地面 y 与 max(yA, yB) 差超过 MAX_FALL_DISTANCE（默认 3m）→
 *       中间有大落差（深沟）→ 不可走；
 *     - 命中地面 y 比 max(yA, yB) 高超过 maxStepHeight（默认 1.5m）→
 *       中间有高墙顶 → 不可走（两端必须翻墙才能互通）；
 *     - 否则该采样点合法。
 *
 *   三个采样点全部合法才视为该段可走。
 *
 * ------------------------------------------------------------------
 * 预计算：把所有 4 邻接边都过一遍，存到 `passRight/passDown` 两张 Uint8 表
 * ------------------------------------------------------------------
 *
 * - `passRight[idx]`：cell idx 与右邻 (idx+1) 之间是否可走（0/1）。
 * - `passDown[idx]` ：cell idx 与下邻 (idx+width) 之间是否可走（0/1）。
 *
 * 表的存在让 A* / BFS 在 `tryRelax` / `tryPush` 中做 O(1) 查表，**寻路全程无射线
 * 开销**。预计算只在两侧都 walkable=1 的边上做（绝大多数 walkable=1 cell
 * 的 4 个邻居要么不可走、要么同 module 且高差极小 —— 后者还可以再优化：
 * 同 module 且 |Δy| ≤ 0.3m 直接判 1，省下大量射线）。
 *
 * 复杂度：n_edges_to_check × 3 raycast（向下，整个地形 mesh）。
 * 中等场景（width × height ≈ 1024²，walkable 率 30%）边数 ~30 万，
 * 9e5 次 raycast，分帧执行约 5~15s（取决于 mesh 复杂度）。
 */

/** 段落检测默认参数（沿用 viewer-sdk 玩家配置） */
export const SEGMENT_CHECK_DEFAULTS = {
  /** 一步可跨上去的最大高差（米）：两端 y 差 ≤ 此值视为同层；中段 y 高出两端 ≤ 此值 ok */
  MAX_STEP_HEIGHT: 1.5,
  /** 视为悬崖的最大落差（米）：中段 y 比两端低超过此值即不可走 */
  MAX_FALL_DISTANCE: 3.0,
  /** 射线起点抬高（米）：从地面往上 0.5m 起射，避开自身碰撞 */
  RAY_ORIGIN_HEIGHT: 0.5,
  /** 中段采样点数（含两端之间） */
  SAMPLES: 3,
  /** 同 module 内 |Δy| ≤ 此值的边直接判可走，跳过射线检测（性能优化） */
  TRIVIAL_SAME_MODULE_DY: 0.3,
  /** 单帧最多处理多少条边（分帧调度，避免阻塞主线程） */
  BATCH_EDGES_PER_FRAME: 5000
} as const

export interface SegmentCheckOptions {
  maxStepHeight?: number
  maxFallDistance?: number
  rayOriginHeight?: number
  samples?: number
  trivialSameModuleDy?: number
  batchEdgesPerFrame?: number
  /** 分帧进度回调（0~1） */
  onProgress?: (p: number) => void
}

/**
 * 预计算 walkableMap 上所有 4 邻接边的段落可通性，并把 passRight/passDown
 * 写回 map。已存在则跳过（除非 force=true）。
 *
 * @param map           当前 walkableMap（必须先栅格化）
 * @param force         为 true 时强制重新计算（默认 false，已有结果就跳过）
 * @param options       检测参数
 * @returns true=预计算成功 / false=失败（无 mesh、无 map 等）
 */
export async function prepareEdgePassability(
  map: WalkableMap,
  force = false,
  options: SegmentCheckOptions = {}
): Promise<boolean> {
  if (!map) return false
  if (!force && map.passRight && map.passDown) return true

  // 收集主场景 mesh —— 与 useRasterizer 同源
  const terrainStore = useTerrainStore()
  const meshes: Mesh[] = []
  const terrainRoots: Object3D[] = terrainStore.terrains.map((t) => t.object3D)
  for (const root of terrainRoots) {
    root.updateMatrixWorld(true)
    root.traverse((obj) => {
      const m = obj as Mesh
      if (m.isMesh && m.geometry) meshes.push(m)
    })
  }
  if (meshes.length === 0) {
    console.error('[SegmentCheck] 主预览区没有地形 mesh')
    return false
  }

  const maxStep = options.maxStepHeight ?? SEGMENT_CHECK_DEFAULTS.MAX_STEP_HEIGHT
  const maxFall = options.maxFallDistance ?? SEGMENT_CHECK_DEFAULTS.MAX_FALL_DISTANCE
  const rayUp = options.rayOriginHeight ?? SEGMENT_CHECK_DEFAULTS.RAY_ORIGIN_HEIGHT
  const samples = Math.max(1, options.samples ?? SEGMENT_CHECK_DEFAULTS.SAMPLES)
  const trivialDy = options.trivialSameModuleDy ?? SEGMENT_CHECK_DEFAULTS.TRIVIAL_SAME_MODULE_DY
  const batch = options.batchEdgesPerFrame ?? SEGMENT_CHECK_DEFAULTS.BATCH_EDGES_PER_FRAME

  const { width, height, originX, originZ, cellSize, walkable, moduleIdMap, heightMap } = map
  const total = width * height
  const passRight = new Uint8Array(total)
  const passDown = new Uint8Array(total)

  const raycaster = new Raycaster()
  raycaster.ray.direction.set(0, -1, 0)
  // 注意：与栅格化一致，**不能**开 firstHitOnly —— 需要遍历命中跳过屋顶。

  // 复用对象，减少 GC
  const origin = new Vector3()
  const dirDown = new Vector3(0, -1, 0)
  const normalWorld = new Vector3()

  /**
   * 段落可通性核心算法：A→B 之间做 `samples` 个等分采样点，
   * 每点向下射线，要求命中地面 y 满足：
   *   minY - maxStep ≤ groundY ≤ maxY + maxStep
   * 且任一点未命中（深渊）即视为不可走。
   *
   * 注：左右额外 SAFETY_MARGIN 偏移检测在两点段中意义不大（两 cell 中心
   * 距离 = cellSize ≈ 0.3~0.5m，与 viewer-sdk 玩家的 0.1 偏移同量级），
   * 故省略，沿主轴 3 点即可。如发现误判可再加左右偏移。
   */
  function passSegment(
    aIdx: number,
    bIdx: number,
    yA: number,
    yB: number
  ): boolean {
    // 端点世界坐标（cell 中心）
    const ai = aIdx % width
    const aj = (aIdx - ai) / width
    const bi = bIdx % width
    const bj = (bIdx - bi) / width
    const ax = originX + (ai + 0.5) * cellSize
    const az = originZ + (aj + 0.5) * cellSize
    const bx = originX + (bi + 0.5) * cellSize
    const bz = originZ + (bj + 0.5) * cellSize

    const yMin = Math.min(yA, yB)
    const yMax = Math.max(yA, yB)
    // 射线起点抬高基准：两端较高那侧 + RAY_ORIGIN_HEIGHT
    const rayStartY = yMax + rayUp
    // 射线最大长度：覆盖到 yMin - maxFall - 余量（足以打到深沟底以下）
    const rayFar = (rayStartY - yMin) + maxFall + rayUp + 2.0

    raycaster.far = rayFar
    raycaster.ray.direction.copy(dirDown)

    // 采样：等分两端之间（不含端点本身），samples=3 → 0.25/0.5/0.75
    for (let s = 1; s <= samples; s++) {
      const t = s / (samples + 1)
      const px = ax + (bx - ax) * t
      const pz = az + (bz - az) * t
      origin.set(px, rayStartY, pz)
      raycaster.ray.origin.copy(origin)

      const hits = raycaster.intersectObjects(meshes, false)
      if (hits.length === 0) {
        // 中段完全无地面 → 深渊，不可走
        return false
      }
      // 取首个"法线朝上"的命中作为地面（与栅格化一致）。
      // **关键**：必须用 `transformDirection(matrixWorld)` 把法线转到世界系
      // 再判 .y > 0；直接用 `hit.face.normal.y` 在 mesh 有任何旋转/缩放时
      // 会全部判错，导致绝大多数边被误判为"无地面"→不可走。
      let groundY = NaN
      for (let hi = 0; hi < hits.length; hi++) {
        const hit = hits[hi]
        if (!hit.face) {
          // 没有 face 信息：与栅格化行为一致，视为合法地面
          groundY = hit.point.y
          break
        }
        normalWorld
          .copy(hit.face.normal)
          .transformDirection(hit.object.matrixWorld)
          .normalize()
        if (normalWorld.y > 0) {
          groundY = hit.point.y
          break
        }
      }
      if (!Number.isFinite(groundY)) {
        // 全是倒挂面（拱顶/桥底）→ 视为无地面
        return false
      }

      // 判定区间：[yMin - maxFall, yMax + maxStep]
      // - groundY < yMin - maxFall：地面比两端最低还低 maxFall 以上 → 深沟
      // - groundY > yMax + maxStep：地面比两端最高还高 maxStep 以上 → 高墙
      if (groundY < yMin - maxFall) return false
      if (groundY > yMax + maxStep) return false
    }
    return true
  }

  // 统计要处理的边数（仅 walkable=1 的右/下邻接）
  let totalEdges = 0
  for (let j = 0; j < height; j++) {
    for (let i = 0; i < width; i++) {
      const idx = j * width + i
      if (walkable[idx] !== 1) continue
      if (i + 1 < width && walkable[idx + 1] === 1) totalEdges++
      if (j + 1 < height && walkable[idx + width] === 1) totalEdges++
    }
  }
  if (totalEdges === 0) {
    map.passRight = passRight
    map.passDown = passDown
    return true
  }

  // 分帧执行：按行扫描，每帧处理 `batch` 条边
  let processed = 0
  let cursorJ = 0
  let cursorI = 0
  let cursorAxis: 0 | 1 = 0 // 0=右, 1=下

  await new Promise<void>((resolve) => {
    function step() {
      let count = 0
      while (count < batch && cursorJ < height) {
        const idx = cursorJ * width + cursorI
        if (walkable[idx] === 1) {
          if (cursorAxis === 0) {
            if (cursorI + 1 < width && walkable[idx + 1] === 1) {
              const yA = heightMap[idx]
              const yB = heightMap[idx + 1]
              let pass: boolean
              if (
                Number.isFinite(yA) &&
                Number.isFinite(yB) &&
                moduleIdMap[idx] === moduleIdMap[idx + 1] &&
                moduleIdMap[idx] > 0 &&
                Math.abs(yA - yB) <= trivialDy
              ) {
                // 同 module 同高度 → 直接判可走，省一次 raycast
                pass = true
              } else if (!Number.isFinite(yA) || !Number.isFinite(yB)) {
                // 端点 heightMap 为 NaN（理论上 walkable=1 不会 NaN，保守判可）
                pass = true
              } else {
                pass = passSegment(idx, idx + 1, yA, yB)
              }
              passRight[idx] = pass ? 1 : 0
              processed++
              count++
            }
            cursorAxis = 1
            continue
          }
          if (cursorAxis === 1) {
            if (cursorJ + 1 < height && walkable[idx + width] === 1) {
              const yA = heightMap[idx]
              const yB = heightMap[idx + width]
              let pass: boolean
              if (
                Number.isFinite(yA) &&
                Number.isFinite(yB) &&
                moduleIdMap[idx] === moduleIdMap[idx + width] &&
                moduleIdMap[idx] > 0 &&
                Math.abs(yA - yB) <= trivialDy
              ) {
                pass = true
              } else if (!Number.isFinite(yA) || !Number.isFinite(yB)) {
                pass = true
              } else {
                pass = passSegment(idx, idx + width, yA, yB)
              }
              passDown[idx] = pass ? 1 : 0
              processed++
              count++
            }
            cursorAxis = 0
            cursorI++
            if (cursorI >= width) {
              cursorI = 0
              cursorJ++
            }
            continue
          }
        } else {
          // 不可走 cell：无需处理边
          cursorAxis = 0
          cursorI++
          if (cursorI >= width) {
            cursorI = 0
            cursorJ++
          }
        }
      }

      if (options.onProgress) options.onProgress(processed / totalEdges)

      if (cursorJ >= height) {
        resolve()
        return
      }
      schedule(step)
    }
    schedule(step)
  })

  map.passRight = passRight
  map.passDown = passDown
  console.log(`[SegmentCheck] 预计算完成：edges=${totalEdges}, pass=${countPass(passRight) + countPass(passDown)} (${(((countPass(passRight) + countPass(passDown)) / totalEdges) * 100).toFixed(1)}%)`)
  return true
}

function countPass(a: Uint8Array): number {
  let c = 0
  for (let i = 0; i < a.length; i++) if (a[i] === 1) c++
  return c
}

function schedule(cb: () => void) {
  const ric = (window as unknown as {
    requestIdleCallback?: (cb: () => void, opts?: { timeout?: number }) => number
  }).requestIdleCallback
  if (typeof ric === 'function') {
    ric(() => cb(), { timeout: 50 })
  } else {
    setTimeout(cb, 0)
  }
}

/**
 * 运行时 O(1) 查询：两个 4 邻接 cell 之间是否可走（基于预计算结果）。
 *
 * - 若 `passRight/passDown` 未预计算，返回 null（调用方应降级到 heightMap 判定）。
 * - 仅支持 4 邻接（|di|+|dj|=1）；非邻接返回 null。
 */
export function isSegmentPassable(
  map: WalkableMap,
  fromIdx: number,
  toIdx: number
): boolean | null {
  const passRight = map.passRight
  const passDown = map.passDown
  if (!passRight || !passDown) return null
  const diff = toIdx - fromIdx
  if (diff === 1) return passRight[fromIdx] === 1
  if (diff === -1) return passRight[toIdx] === 1
  if (diff === map.width) return passDown[fromIdx] === 1
  if (diff === -map.width) return passDown[toIdx] === 1
  return null
}
