import { Mesh, Object3D, Raycaster, Vector3 } from 'three'
import type { ModuleRuntime } from '../types/modules'
import type { Anchor } from '../stores/anchors'
import { useTerrainStore } from '../stores/terrain'

/**
 * ============================================================
 * 轻量 anchor 吸附（方案 D 配套）
 * ============================================================
 *
 * 目的：把"生成默认 anchor"从依赖全图 walkableMap 解耦出来。
 *
 * 与 useDefaultAnchors 的区别：
 *   - useDefaultAnchors：依赖已栅格化的 walkableMap，用 spiralFindWalkable
 *     在栅格上吸附 → 必须先做一次"全图栅格化"（最慢的一步）。
 *   - useAnchorSnap：仅对每个 module 中心做 **1 次顶视 raycast**，
 *     直接命中地面 mesh，零栅格化依赖。N modules → N 次 raycast，~ms 级。
 *
 * 复用：射线规则、坡度过滤与栅格化保持完全一致（同一份"地面定义"），
 * 确保 anchor 落点与后续局部栅格化的 walkable=1 cell 在同一物理位置。
 *
 * 注意：anchor 数据结构中的 cellIdx 在本方案下**不参与全图扩散**，
 * 仅作为兼容字段保留（在局部 walkableMap 上按需重新换算）。
 * ============================================================
 */

const SKY_OFFSET = 200
const RAY_FAR_PADDING = 200

export interface AnchorSnapOptions {
  /** 坡度阈值（度），与 useRasterizer 同一概念 */
  slopeThresholdDeg: number
}

export interface LightAnchor extends Anchor {
  /** 命中地面的世界 y 高度（用于局部栅格化与可视化校验） */
  worldY: number
}

export interface BuildLightAnchorsResult {
  anchors: Map<string, LightAnchor[]>
  warnings: Array<{ moduleName: string; reason: string }>
  stats: { total: number; success: number; failed: number; elapsedMs: number }
}

/**
 * 收集主场景所有地形 mesh（与 useRasterizer / useSegmentWalkable 同源）。
 */
function collectTerrainMeshes(): Mesh[] {
  const terrainStore = useTerrainStore()
  const meshes: Mesh[] = []
  const roots: Object3D[] = terrainStore.terrains.map((t) => t.object3D)
  for (const root of roots) {
    root.updateMatrixWorld(true)
    root.traverse((obj) => {
      const m = obj as Mesh
      if (m.isMesh && m.geometry) meshes.push(m)
    })
  }
  return meshes
}

/**
 * 顶视 raycast 找"法线朝上、坡度合格"的地面 y。
 * 与 useRasterizer 的"groundIdx"语义完全一致。
 *
 * @returns 命中地面的 y；若无合法地面返回 null
 */
export function raycastGroundY(
  meshes: Mesh[],
  worldX: number,
  worldZ: number,
  yMin: number,
  yMax: number,
  slopeCos: number,
  raycaster?: Raycaster,
  normalScratch?: Vector3
): number | null {
  const rc = raycaster ?? new Raycaster()
  rc.ray.direction.set(0, -1, 0)
  rc.far = yMax - yMin + SKY_OFFSET + RAY_FAR_PADDING
  rc.ray.origin.set(worldX, yMax + SKY_OFFSET, worldZ)
  const hits = rc.intersectObjects(meshes, false)
  if (hits.length === 0) return null
  const nw = normalScratch ?? new Vector3()
  for (let i = 0; i < hits.length; i++) {
    const h = hits[i]
    if (!h.face) return h.point.y
    nw.copy(h.face.normal).transformDirection(h.object.matrixWorld).normalize()
    if (nw.y >= slopeCos) return h.point.y
  }
  return null
}

/**
 * 为每个已加载 module 生成 1 个默认 anchor（取 worldBox XZ 中心 + 顶视吸附）。
 *
 * 失败场景：
 *   - module 未加载 / worldBox 为空
 *   - 中心点上方射线没命中任何 mesh
 *   - 命中的全是屋顶 / 倒挂面（无法线朝上的命中）
 *
 * 失败的 module 进 warnings，用户可在 minimap 手工补点（沿用现有交互）。
 */
export function buildLightDefaultAnchors(
  modules: ModuleRuntime[],
  opts: AnchorSnapOptions
): BuildLightAnchorsResult {
  const t0 = performance.now()
  const out = new Map<string, LightAnchor[]>()
  const warnings: Array<{ moduleName: string; reason: string }> = []
  let success = 0
  let failed = 0

  const meshes = collectTerrainMeshes()
  if (meshes.length === 0) {
    return {
      anchors: out,
      warnings: [{ moduleName: '(global)', reason: '主预览区没有地形 mesh' }],
      stats: { total: 0, success: 0, failed: 0, elapsedMs: 0 }
    }
  }

  // 计算全局 y 区间，用于射线 far 上限
  let gYMin = Infinity
  let gYMax = -Infinity
  for (const m of modules) {
    if (!m.loaded || m.worldBox.isEmpty()) continue
    if (m.worldBox.min.y < gYMin) gYMin = m.worldBox.min.y
    if (m.worldBox.max.y > gYMax) gYMax = m.worldBox.max.y
  }
  if (!Number.isFinite(gYMin) || !Number.isFinite(gYMax)) {
    return {
      anchors: out,
      warnings: [{ moduleName: '(global)', reason: '没有已加载 module 可计算 y 范围' }],
      stats: { total: 0, success: 0, failed: 0, elapsedMs: 0 }
    }
  }

  const slopeCos = Math.cos((opts.slopeThresholdDeg * Math.PI) / 180)
  const raycaster = new Raycaster()
  const normalScratch = new Vector3()
  const tmpCenter = new Vector3()
  const loadedTotal = modules.filter((m) => m.loaded).length

  for (const m of modules) {
    if (!m.loaded) continue
    if (m.worldBox.isEmpty()) {
      warnings.push({ moduleName: m.name, reason: 'worldBox 为空（未加载）' })
      failed++
      continue
    }
    m.worldBox.getCenter(tmpCenter)
    const cx = tmpCenter.x
    const cz = tmpCenter.z
    const groundY = raycastGroundY(meshes, cx, cz, gYMin, gYMax, slopeCos, raycaster, normalScratch)
    if (groundY === null) {
      warnings.push({
        moduleName: m.name,
        reason: '中心点上方无可走面（射线无命中 / 全是屋顶/倒挂面）'
      })
      failed++
      continue
    }
    const anchor: LightAnchor = {
      id: `${m.name}#1`,
      moduleName: m.name,
      worldX: cx,
      worldZ: cz,
      cellIdx: -1, // 局部栅格化时再换算
      isDefault: true,
      worldY: groundY
    }
    out.set(m.name, [anchor])
    success++
  }

  const elapsedMs = performance.now() - t0
  return {
    anchors: out,
    warnings,
    stats: { total: loadedTotal, success, failed, elapsedMs }
  }
}

/**
 * 用户手动添加 anchor 的轻量吸附：
 *   - 单点 raycast 找地面 y；
 *   - 失败返回 null，调用方提示"该位置不可走"。
 */
export function snapAnchorPointLight(
  worldX: number,
  worldZ: number,
  opts: AnchorSnapOptions
): { worldX: number; worldZ: number; worldY: number } | null {
  const meshes = collectTerrainMeshes()
  if (meshes.length === 0) return null
  let gYMin = Infinity
  let gYMax = -Infinity
  for (const mesh of meshes) {
    mesh.geometry.computeBoundingBox()
    const bb = mesh.geometry.boundingBox
    if (!bb) continue
    const min = bb.min.clone().applyMatrix4(mesh.matrixWorld)
    const max = bb.max.clone().applyMatrix4(mesh.matrixWorld)
    if (Math.min(min.y, max.y) < gYMin) gYMin = Math.min(min.y, max.y)
    if (Math.max(min.y, max.y) > gYMax) gYMax = Math.max(min.y, max.y)
  }
  if (!Number.isFinite(gYMin) || !Number.isFinite(gYMax)) return null
  const slopeCos = Math.cos((opts.slopeThresholdDeg * Math.PI) / 180)
  const y = raycastGroundY(meshes, worldX, worldZ, gYMin, gYMax, slopeCos)
  if (y === null) return null
  return { worldX, worldZ, worldY: y }
}
