import type { WalkableMap } from '../types/modules'
import {
  defaultSnapRadius,
  makePassEdge,
  MinHeap,
  spiralFindWalkable,
  worldToCell
} from './walkableUtils'

/**
 * ============================================================
 * 局部 walkableMap 上的 anchor 对 A* 可达测试
 * ============================================================
 *
 * 输入：两个 anchor 的世界坐标 + 一张局部 WalkableMap（含 passRight/passDown）
 * 输出：true=可达 / false=不可达 / null=anchor 落在 map 范围外
 *
 * 关键约定：
 *   - anchor 坐标若不在 map 矩形内 → 返回 null（视为"该对不参与此 map 的测试"）
 *   - 落到不可走 cell → spiralFindWalkable 螺旋吸附（与全图方案一致口径）
 *   - 启发函数：4 邻接曼哈顿（admissible，A* 最优）
 *   - 配额：默认 max(width*height, 50000)；超限保守判 false
 *
 * 为什么不复用 useAStarReachability：
 *   那是"单源全图扩散"，本工具是"单对单 A*"，目标可控、提前剪枝、内存更省。
 * ============================================================
 */

export interface AnchorPairAStarOptions {
  /** 最大 pop 次数（防退化）；默认 max(width*height, 50000) */
  maxIterations?: number
  /** 螺旋吸附半径（默认沿用 walkableUtils.defaultSnapRadius） */
  snapRadius?: number
}

export interface AnchorPairAStarResult {
  reachable: boolean
  /** 起点/终点是否在 map 内（false 表示 anchor 落到 box 外） */
  startInMap: boolean
  goalInMap: boolean
  /** 吸附后的 cell 下标（-1 表示未吸附成功 / 不在 map 内） */
  startCellIdx: number
  goalCellIdx: number
  /** pop 次数 */
  iterations: number
  elapsedMs: number
}

/** anchor (worldX, worldZ) 在 map 上的吸附 */
function snapAnchorOnLocalMap(
  map: WalkableMap,
  worldX: number,
  worldZ: number,
  snapR: number
): { cellIdx: number; inMap: boolean } {
  // 范围检查（半开区间，因为 originX+width*cellSize 是右边界）
  const dx = worldX - map.originX
  const dz = worldZ - map.originZ
  if (dx < 0 || dz < 0 || dx >= map.width * map.cellSize || dz >= map.height * map.cellSize) {
    return { cellIdx: -1, inMap: false }
  }
  const { i, j } = worldToCell(map, worldX, worldZ)
  let cellIdx = j * map.width + i
  if (map.walkable[cellIdx] !== 1) {
    const found = spiralFindWalkable(map.walkable, map.width, map.height, i, j, snapR)
    if (!found) return { cellIdx: -1, inMap: true }
    cellIdx = found.j * map.width + found.i
  }
  return { cellIdx, inMap: true }
}

/**
 * 测试 anchor A → anchor B 在局部 map 上是否 A* 可达。
 *
 * @returns reachable=true/false；若任一 anchor 不在 map 内，reachable=false 且 startInMap/goalInMap 标记
 */
export function testAnchorPairReachable(
  aWorldX: number,
  aWorldZ: number,
  bWorldX: number,
  bWorldZ: number,
  map: WalkableMap,
  options: AnchorPairAStarOptions = {}
): AnchorPairAStarResult {
  const t0 = performance.now()
  const { width, height, walkable } = map
  const total = width * height
  const maxIter = options.maxIterations ?? Math.max(total, 50_000)
  const snapR = options.snapRadius ?? defaultSnapRadius(width, height)

  const aSnap = snapAnchorOnLocalMap(map, aWorldX, aWorldZ, snapR)
  const bSnap = snapAnchorOnLocalMap(map, bWorldX, bWorldZ, snapR)

  if (!aSnap.inMap || !bSnap.inMap || aSnap.cellIdx < 0 || bSnap.cellIdx < 0) {
    return {
      reachable: false,
      startInMap: aSnap.inMap,
      goalInMap: bSnap.inMap,
      startCellIdx: aSnap.cellIdx,
      goalCellIdx: bSnap.cellIdx,
      iterations: 0,
      elapsedMs: performance.now() - t0
    }
  }

  const start = aSnap.cellIdx
  const goal = bSnap.cellIdx
  if (start === goal) {
    return {
      reachable: true,
      startInMap: true,
      goalInMap: true,
      startCellIdx: start,
      goalCellIdx: goal,
      iterations: 0,
      elapsedMs: performance.now() - t0
    }
  }

  const passEdge = makePassEdge(map)
  const gScore = new Int32Array(total).fill(0x7fffffff)
  const closed = new Uint8Array(total)
  gScore[start] = 0
  const heap = new MinHeap()

  // 启发：曼哈顿（4 邻接）
  const goalI = goal % width
  const goalJ = (goal - goalI) / width
  function h(idx: number): number {
    const i = idx % width
    const j = (idx - i) / width
    return Math.abs(i - goalI) + Math.abs(j - goalJ)
  }
  heap.push(h(start), start)

  let iter = 0
  let found = false
  while (heap.size > 0) {
    const node = heap.pop()
    if (!node) break
    iter++
    if (iter > maxIter) break
    const idx = node.idx
    if (idx === goal) {
      found = true
      break
    }
    if (closed[idx]) continue
    closed[idx] = 1
    const g = gScore[idx]
    const ci = idx % width
    const cj = (idx - ci) / width
    const tentativeG = g + 1

    if (ci > 0) relax(idx - 1, idx, tentativeG)
    if (ci < width - 1) relax(idx + 1, idx, tentativeG)
    if (cj > 0) relax(idx - width, idx, tentativeG)
    if (cj < height - 1) relax(idx + width, idx, tentativeG)
  }

  function relax(nIdx: number, fromIdx: number, tentativeG: number) {
    if (walkable[nIdx] !== 1) return
    if (closed[nIdx]) return
    if (!passEdge(fromIdx, nIdx)) return
    if (tentativeG < gScore[nIdx]) {
      gScore[nIdx] = tentativeG
      heap.push(tentativeG + h(nIdx), nIdx)
    }
  }

  return {
    reachable: found,
    startInMap: true,
    goalInMap: true,
    startCellIdx: start,
    goalCellIdx: goal,
    iterations: iter,
    elapsedMs: performance.now() - t0
  }
}
