<script setup lang="ts">
import { computed, ref } from 'vue'
import {
  MapPin, Plus, X, Sparkles, Wand2, Loader2, ChevronDown, ChevronRight,
  Info, Crosshair, Trash2, Network, Download
} from 'lucide-vue-next'
import { useModulesStore } from '../stores/modules'
import { useAnchorStore } from '../stores/anchors'
import { buildLightDefaultAnchors } from '../composables/useAnchorSnap'
import { computeAnchorReachabilityLocal } from '../composables/useAnchorReachabilityLocal'
import { downloadAnchorAnnotatedManifestJson } from '../composables/useAnchorReachabilityExport'

/**
 * AnchorPanel：可达点管理 + 邻接推导（候选剪枝 + 局部 A*）。
 *
 * UI 分区：
 *   1) 标题栏 + 计数胶囊
 *   2) 候选阈值 + 悬崖检测开关
 *   3) 工具条：生成默认 / 计算邻接 / 清空
 *   4) 警告提示（生成默认时失败的 module）
 *   5) 分组列表：按 module 折叠组，组头显示 module 名 + anchor 数 + "+" 添加按钮
 *      展开后表格列出 anchors（id 短码、世界 xz、默认/手工 tag、删除按钮）
 *   6) 结果折叠：moduleTopology + 导出
 */

const modulesStore = useModulesStore()
const anchorStore = useAnchorStore()

const expandedGroups = ref<Set<string>>(new Set())
const showWarnings = ref(true)
const showResultPanel = ref(true)
const lastWarnings = ref<Array<{ moduleName: string; reason: string }>>([])

/** 候选剪枝阈值（米） */
const candidatePadding = ref<number>(2.0)

/** 进度（candidate pair 计数） */
const localProgress = ref<{ done: number; total: number } | null>(null)

const canGenerate = computed(
  () => modulesStore.hasManifest && modulesStore.loadedModuleCount > 0 && !anchorStore.isComputing
)

const canCompute = computed(
  () => modulesStore.hasManifest && anchorStore.totalAnchorCount >= 2 && !anchorStore.isComputing
)

const groupedRows = computed<Array<{ moduleName: string; anchors: ReturnType<typeof anchorStore.getByModule> }>>(() => {
  void anchorStore.revision
  // 按 modules 顺序展示（包括无 anchor 的 module）
  const out: Array<{ moduleName: string; anchors: ReturnType<typeof anchorStore.getByModule> }> = []
  for (const m of modulesStore.modules) {
    if (!m.loaded) continue
    out.push({ moduleName: m.name, anchors: anchorStore.getByModule(m.name) })
  }
  return out
})

const stats = computed(() => {
  void anchorStore.revision
  return {
    anchors: anchorStore.totalAnchorCount,
    modules: anchorStore.moduleNamesWithAnchors.length,
    pairs: anchorStore.result?.stats.reachablePairCount ?? 0,
    edges: anchorStore.result?.stats.moduleEdgeCount ?? 0,
    elapsedMs: anchorStore.result?.stats.elapsedMs ?? 0
  }
})

function toggleGroup(name: string) {
  if (expandedGroups.value.has(name)) expandedGroups.value.delete(name)
  else expandedGroups.value.add(name)
  // 触发响应
  expandedGroups.value = new Set(expandedGroups.value)
}

async function onGenerateDefaults() {
  if (!canGenerate.value) return
  anchorStore.setComputing(true)
  try {
    // 轻量 raycast 吸附，无需全图栅格化
    const r = buildLightDefaultAnchors(modulesStore.modules, {
      slopeThresholdDeg: modulesStore.slopeThresholdDeg
    })
    anchorStore.setAll(r.anchors)
    lastWarnings.value = r.warnings
    showWarnings.value = r.warnings.length > 0
    console.log(
      `[Anchor] 默认 anchors 生成: total=${r.stats.total}, success=${r.stats.success}, ` +
        `failed=${r.stats.failed}, elapsed=${r.stats.elapsedMs.toFixed(1)}ms`
    )
  } finally {
    anchorStore.setComputing(false)
  }
}

async function onCompute() {
  if (!canCompute.value) return
  anchorStore.setComputing(true)
  localProgress.value = null
  try {
    // 候选剪枝 + 局部 A*
    const all = anchorStore.allAnchors
    const r = await computeAnchorReachabilityLocal(all, modulesStore.modules, {
      padding: candidatePadding.value,
      useSegmentCheck: anchorStore.useSegmentCheck,
      onProgress: (done, total) => {
        localProgress.value = { done, total }
      }
    })
    anchorStore.setResult(r)
  } finally {
    anchorStore.setComputing(false)
    localProgress.value = null
  }
}

function onClear() {
  anchorStore.clearAll()
  lastWarnings.value = []
}

function onAddToModule(name: string) {
  if (anchorStore.addModeModuleName === name) {
    anchorStore.leaveAddMode()
  } else {
    anchorStore.enterAddMode(name)
  }
}

function onRemoveAnchor(id: string, ev: Event) {
  ev.stopPropagation()
  anchorStore.removeAnchor(id)
}

function onAnchorClick(id: string) {
  if (anchorStore.selectedAnchorId === id) {
    anchorStore.selectAnchor(null)
  } else {
    anchorStore.selectAnchor(id)
  }
}

function onAnchorHover(id: string | null) {
  anchorStore.setHovered(id)
}

const inAddMode = computed(() => anchorStore.addModeModuleName !== null)

/** 导出在原 manifest 基础上附加 reachableNeighbors 字段的 module JSON */
function onExportManifest() {
  if (!anchorStore.hasResult || !modulesStore.hasManifest) return
  try {
    downloadAnchorAnnotatedManifestJson()
  } catch (e) {
    console.error('[Anchor] 导出 manifest 失败：', e)
  }
}
</script>

<template>
  <div class="glass-card p-3 flex flex-col gap-2.5 max-h-[52vh]">
    <!-- 标题栏 -->
    <div class="flex items-center justify-between px-1">
      <div class="flex items-center gap-2">
        <MapPin class="w-4 h-4 text-fuchsia-400" />
        <span class="text-sm font-semibold tracking-wide">Anchor 管理 + 邻接</span>
      </div>
      <div class="flex items-center gap-1 text-[10px] font-mono text-slate-400">
        <span class="chip">{{ stats.anchors }} pts</span>
        <span class="chip" v-if="stats.pairs > 0">{{ stats.pairs }} pairs</span>
        <span class="chip text-emerald-300/80 border-emerald-400/30" v-if="stats.edges > 0">
          {{ stats.edges }} edges
        </span>
      </div>
    </div>

    <!-- 候选 padding + 进度 + 悬崖检测 -->
    <div class="flex flex-col gap-1.5 px-0.5">
      <div class="flex items-center gap-2 text-[10px] text-slate-400">
        <span class="shrink-0">候选阈值</span>
        <input
          type="range"
          min="0"
          max="10"
          step="0.5"
          :value="candidatePadding"
          @input="(e) => candidatePadding = Number((e.target as HTMLInputElement).value)"
          class="flex-1 accent-fuchsia-400"
          title="两 module XZ 间距 ≤ 此值才视为候选对（米）"
        />
        <span class="font-mono text-fuchsia-300 w-10 text-right">{{ candidatePadding.toFixed(1) }}m</span>
        <span
          v-if="localProgress"
          class="text-emerald-300/80 font-mono ml-1"
        >
          {{ localProgress.done }}/{{ localProgress.total }}
        </span>
      </div>
      <!-- 悬崖检测开关：影响 candidate pair 的边可走判定 -->
      <label
        class="flex items-center gap-1.5 text-[10px] text-slate-400 cursor-pointer select-none"
        title="A→B 之间向下射线，精确识别高墙/深沟/夹层"
      >
        <input
          type="checkbox"
          :checked="anchorStore.useSegmentCheck"
          class="accent-fuchsia-400"
          @change="(e) => anchorStore.setUseSegmentCheck((e.target as HTMLInputElement).checked)"
        />
        <span class="text-slate-300">启用悬崖检测（segment check）</span>
      </label>
    </div>

    <!-- 工具条 -->
    <div class="grid grid-cols-3 gap-1.5">
      <button
        class="btn-cyan justify-center"
        :disabled="!canGenerate"
        :class="{ 'opacity-50 cursor-not-allowed hover:translate-y-0 hover:border-white/10 hover:text-slate-100 hover:shadow-none': !canGenerate }"
        title="对每个 module 取 worldBox 中心吸附为默认 anchor"
        @click="onGenerateDefaults"
      >
        <Wand2 class="w-3.5 h-3.5" />
        <span>生成默认</span>
      </button>
      <button
        class="btn-cyan justify-center"
        :disabled="!canCompute"
        :class="{ 'opacity-50 cursor-not-allowed hover:translate-y-0 hover:border-white/10 hover:text-slate-100 hover:shadow-none': !canCompute }"
        title="候选剪枝 + 局部 A*：anchor 两两可达 → 推导 module 邻接"
        @click="onCompute"
      >
        <Loader2 v-if="anchorStore.isComputing" class="w-3.5 h-3.5 animate-spin" />
        <Sparkles v-else class="w-3.5 h-3.5" />
        <span>{{ anchorStore.hasResult ? '重算邻接' : '计算邻接' }}</span>
      </button>
      <button
        class="btn-cyan justify-center"
        :disabled="anchorStore.totalAnchorCount === 0"
        :class="{ 'opacity-50 cursor-not-allowed hover:translate-y-0 hover:border-white/10 hover:text-slate-100 hover:shadow-none': anchorStore.totalAnchorCount === 0 }"
        title="清空所有 anchor 与计算结果"
        @click="onClear"
      >
        <Trash2 class="w-3.5 h-3.5" />
        <span>清空</span>
      </button>
    </div>

    <!-- 添加模式提示 -->
    <div
      v-if="inAddMode"
      class="rounded-md bg-fuchsia-500/15 border border-fuchsia-400/40 px-3 py-2 text-[11px] text-fuchsia-200 flex items-center gap-2"
    >
      <Crosshair class="w-3.5 h-3.5 shrink-0 animate-pulse" />
      <span class="flex-1">
        添加模式：在 minimap 点击
        <span class="font-mono text-fuchsia-300">{{ anchorStore.addModeModuleName }}</span>
        范围内的可走区域
      </span>
      <button
        class="text-fuchsia-300/80 hover:text-fuchsia-200 cursor-pointer"
        title="取消添加模式"
        @click="anchorStore.leaveAddMode()"
      >
        <X class="w-3.5 h-3.5" />
      </button>
    </div>

    <!-- 设计说明 tooltip -->
    <div
      class="rounded-md bg-amber-500/10 border border-amber-400/25 px-3 py-1.5 text-[10px] text-amber-200/90 flex items-start gap-1.5"
    >
      <Info class="w-3 h-3 shrink-0 mt-0.5 opacity-80" />
      <span>
        anchor 推导默认 = "A 任一 anchor 能到 B 任一 anchor"，会保留可达传递性
        （A→C 必经 B 时 A-C 也算邻接）。
      </span>
    </div>

    <!-- 默认生成警告 -->
    <div
      v-if="lastWarnings.length > 0 && showWarnings"
      class="rounded-md bg-rose-500/10 border border-rose-400/25 px-3 py-2 text-[10px] text-rose-200"
    >
      <div class="flex items-center justify-between mb-1">
        <span class="font-semibold">{{ lastWarnings.length }} 个 module 默认生成失败</span>
        <button class="text-rose-300/70 hover:text-rose-200" @click="showWarnings = false">
          <X class="w-3 h-3" />
        </button>
      </div>
      <ul class="space-y-0.5 max-h-20 overflow-auto scrollbar-thin">
        <li v-for="w in lastWarnings" :key="w.moduleName" class="font-mono text-[10px] truncate" :title="w.reason">
          <span class="text-rose-300">{{ w.moduleName }}</span>
          <span class="text-rose-300/60 mx-1">:</span>
          <span class="text-rose-200/80">{{ w.reason }}</span>
        </li>
      </ul>
    </div>

    <!-- 空状态 -->
    <div
      v-if="!modulesStore.hasManifest"
      class="rounded-lg bg-white/[0.03] border border-dashed border-white/10 px-3 py-3 text-[11px] text-slate-400 text-center"
    >
      请先上传 manifest，加载 module 后再生成 anchors
    </div>

    <!-- 分组列表 -->
    <div
      v-else
      class="flex flex-col gap-1 overflow-auto scrollbar-thin pr-1 flex-1 min-h-0"
    >
      <div
        v-for="g in groupedRows"
        :key="g.moduleName"
        class="rounded-md border border-white/5 bg-white/[0.02]"
      >
        <!-- 组头 -->
        <div
          class="flex items-center gap-1.5 px-2 py-1.5 cursor-pointer hover:bg-white/[0.04] transition-colors"
          @click="toggleGroup(g.moduleName)"
        >
          <component
            :is="expandedGroups.has(g.moduleName) ? ChevronDown : ChevronRight"
            class="w-3 h-3 text-slate-500 shrink-0"
          />
          <span class="text-[11px] font-mono truncate flex-1" :title="g.moduleName">
            {{ g.moduleName }}
          </span>
          <span
            class="text-[10px] font-mono px-1.5 rounded border"
            :class="
              g.anchors.length === 0
                ? 'text-slate-500 border-white/10'
                : 'text-fuchsia-300 border-fuchsia-400/40 bg-fuchsia-400/10'
            "
          >
            {{ g.anchors.length }}
          </span>
          <button
            class="text-[11px] px-1.5 py-0.5 rounded border transition-colors shrink-0"
            :class="
              anchorStore.addModeModuleName === g.moduleName
                ? 'bg-fuchsia-400/20 border-fuchsia-400 text-fuchsia-200'
                : 'border-white/10 text-slate-400 hover:text-slate-200 hover:border-white/20'
            "
            :title="anchorStore.addModeModuleName === g.moduleName ? '退出添加模式' : '在 minimap 上添加'"
            @click.stop="onAddToModule(g.moduleName)"
          >
            <Plus class="w-3 h-3 inline" />
          </button>
        </div>

        <!-- 子列表 -->
        <div
          v-if="expandedGroups.has(g.moduleName) && g.anchors.length > 0"
          class="flex flex-col px-2 pb-1.5 gap-0.5"
        >
          <div
            v-for="a in g.anchors"
            :key="a.id"
            class="group flex items-center gap-1.5 px-1.5 py-1 rounded text-[10px] font-mono cursor-pointer transition-colors"
            :class="
              anchorStore.selectedAnchorId === a.id
                ? 'bg-fuchsia-500/20 border border-fuchsia-400/50'
                : 'bg-white/[0.03] hover:bg-white/[0.06] border border-transparent'
            "
            @mouseenter="onAnchorHover(a.id)"
            @mouseleave="onAnchorHover(null)"
            @click="onAnchorClick(a.id)"
          >
            <span
              class="w-1.5 h-1.5 rounded-full shrink-0"
              :class="a.isDefault ? 'bg-cyan-400' : 'bg-fuchsia-400'"
            />
            <span class="text-slate-300 truncate flex-1">
              ({{ a.worldX.toFixed(1) }}, {{ a.worldZ.toFixed(1) }})
            </span>
            <span
              class="text-[9px] px-1 rounded shrink-0"
              :class="
                a.isDefault
                  ? 'text-cyan-300/80 bg-cyan-400/10'
                  : 'text-fuchsia-300/80 bg-fuchsia-400/10'
              "
            >
              {{ a.isDefault ? '默认' : '手工' }}
            </span>
            <button
              class="text-slate-500 hover:text-rose-400 opacity-0 group-hover:opacity-100 transition-opacity shrink-0"
              title="删除"
              @click="onRemoveAnchor(a.id, $event)"
            >
              <X class="w-3 h-3" />
            </button>
          </div>
        </div>
      </div>
    </div>

    <!-- 结果折叠 -->
    <div v-if="anchorStore.hasResult" class="border-t border-white/5 pt-2">
      <div
        class="flex items-center gap-1.5 px-1 cursor-pointer text-[11px] text-slate-300 hover:text-slate-100"
        @click="showResultPanel = !showResultPanel"
      >
        <component :is="showResultPanel ? ChevronDown : ChevronRight" class="w-3 h-3" />
        <Network class="w-3.5 h-3.5 text-emerald-400" />
        <span class="flex-1">
          可达对 <span class="text-emerald-300">{{ stats.pairs }}</span>
          · module 邻接 <span class="text-emerald-300">{{ stats.edges }}</span>
        </span>
        <span class="text-[9px] text-slate-500 font-mono">{{ stats.elapsedMs.toFixed(0) }}ms</span>
        <button
          class="ml-1 px-1.5 py-0.5 rounded border border-emerald-400/40 text-emerald-300 hover:bg-emerald-400/15 hover:text-emerald-200 transition-colors flex items-center gap-1 text-[10px]"
          :disabled="!modulesStore.hasManifest"
          :class="{ 'opacity-40 cursor-not-allowed hover:bg-transparent': !modulesStore.hasManifest }"
          title="导出在原 manifest 基础上附加 reachableNeighbors 字段的新 JSON"
          @click.stop="onExportManifest"
        >
          <Download class="w-3 h-3" />
          <span>导出 module JSON</span>
        </button>
      </div>
      <div
        v-if="showResultPanel"
        class="mt-1.5 max-h-28 overflow-auto scrollbar-thin text-[10px] font-mono space-y-0.5"
      >
        <div
          v-for="(edge, i) in anchorStore.result!.moduleTopology"
          :key="i"
          class="px-2 py-0.5 rounded bg-white/[0.02] text-slate-300 truncate"
          :title="`${edge[0]} ↔ ${edge[1]}`"
        >
          <span class="text-cyan-300">{{ edge[0] }}</span>
          <span class="text-slate-500 mx-1">↔</span>
          <span class="text-fuchsia-300">{{ edge[1] }}</span>
        </div>
        <div v-if="anchorStore.result!.moduleTopology.length === 0" class="text-slate-500 text-center py-1.5">
          无 module 邻接（anchor 全部孤立）
        </div>
      </div>
    </div>
  </div>
</template>
