<script setup lang="ts">
import { computed, ref } from 'vue'
import { Mouse, MoveDiagonal, RotateCw, Box, MousePointerClick, Crosshair } from 'lucide-vue-next'
import { usePreview } from '../composables/usePreview'
import { useTerrainStore } from '../stores/terrain'
import { useAnchorStore } from '../stores/anchors'

const containerRef = ref<HTMLDivElement | null>(null)
const canvasRef = ref<HTMLCanvasElement | null>(null)
const store = useTerrainStore()
const anchorStore = useAnchorStore()

usePreview({
  canvasRef: () => canvasRef.value,
  containerRef: () => containerRef.value
})

const anchorCount = computed(() => anchorStore.allAnchors.length)
const selectedAnchor = computed(() =>
  anchorStore.selectedAnchorId ? anchorStore.getById(anchorStore.selectedAnchorId) : null
)
</script>

<template>
  <div
    ref="containerRef"
    class="relative w-full h-full overflow-hidden rounded-xl border border-white/5"
  >
    <canvas ref="canvasRef" class="block w-full h-full" />

    <!-- 空状态浮层 -->
    <div
      v-if="store.isEmpty"
      class="absolute inset-0 flex flex-col items-center justify-center pointer-events-none animate-fade-in"
    >
      <div
        class="w-20 h-20 rounded-2xl bg-white/5 border border-white/10 flex items-center justify-center mb-5 shadow-glass"
      >
        <Box class="w-10 h-10 text-cyan-glow" :stroke-width="1.4" />
      </div>
      <div class="text-base font-medium text-slate-200 mb-1.5">
        拖拽 GLB 文件到此处或使用右上角上传
      </div>
      <div class="text-xs text-slate-400">
        支持 .glb / .gltf 格式 · 多文件按世界坐标自动拼接
      </div>
    </div>

    <!-- 顶部 anchor 计数 / 选中信息 -->
    <div
      v-if="!store.isEmpty && anchorCount > 0"
      class="absolute top-2 left-2 right-2 flex items-center justify-between gap-2 pointer-events-none"
    >
      <div
        class="flex items-center gap-1.5 px-2.5 py-1 rounded-md glass-card text-[11px] text-slate-200"
      >
        <Crosshair class="w-3 h-3 text-emerald-300" />
        <span class="font-mono">{{ anchorCount }}</span>
        <span class="text-slate-400">anchors</span>
      </div>
      <div
        v-if="selectedAnchor"
        class="flex items-center gap-1.5 px-2.5 py-1 rounded-md bg-emerald-400/15 border border-emerald-400/40 text-[11px] text-emerald-200 font-mono"
      >
        <span>{{ selectedAnchor.id }}</span>
        <span class="text-emerald-300/70">
          ({{ selectedAnchor.worldX.toFixed(1) }}, {{ selectedAnchor.worldZ.toFixed(1) }})
        </span>
      </div>
    </div>

    <!-- 底部操作提示 -->
    <div
      v-if="!store.isEmpty"
      class="absolute bottom-4 left-1/2 -translate-x-1/2 flex items-center gap-4 px-4 py-2 rounded-full glass-card text-[11px] text-slate-300"
    >
      <span class="flex items-center gap-1.5">
        <RotateCw class="w-3.5 h-3.5 text-cyan-glow" />左键旋转
      </span>
      <span class="w-px h-3 bg-white/10" />
      <span class="flex items-center gap-1.5">
        <Mouse class="w-3.5 h-3.5 text-cyan-glow" />滚轮缩放
      </span>
      <span class="w-px h-3 bg-white/10" />
      <span class="flex items-center gap-1.5">
        <MoveDiagonal class="w-3.5 h-3.5 text-cyan-glow" />右键平移
      </span>
      <span v-if="anchorCount > 0" class="w-px h-3 bg-white/10" />
      <span
        v-if="anchorCount > 0"
        class="flex items-center gap-1.5 text-emerald-300"
      >
        <MousePointerClick class="w-3.5 h-3.5" />点击球选中
      </span>
    </div>
  </div>
</template>
