import { onBeforeUnmount, onMounted, watch } from 'vue'
import {
  Box3,
  Box3Helper,
  BufferGeometry,
  Color,
  Float32BufferAttribute,
  GridHelper,
  Group,
  LineBasicMaterial,
  LineSegments,
  Mesh,
  MeshBasicMaterial,
  PerspectiveCamera,
  Raycaster,
  SphereGeometry,
  Vector2,
  Vector3,
  WebGLRenderer
} from 'three'
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js'
import { useThreeScene } from './useThreeScene'
import { useTerrainStore } from '../stores/terrain'
import { useModulesStore } from '../stores/modules'
import { useAnchorStore, type Anchor } from '../stores/anchors'
import { snapAnchorPointLight } from './useAnchorSnap'

interface UsePreviewOptions {
  canvasRef: () => HTMLCanvasElement | null
  containerRef: () => HTMLElement | null
  /** 点击命中 anchor 球时回调（用于选中 / 取消选中等业务逻辑） */
  onAnchorClick?: (anchorId: string) => void
}

/* ============================================================
 * 3D 预览（方案 A：在 PreviewView 上叠加 anchor 可视化）
 * ------------------------------------------------------------
 * 在共享的 three scene 之上，给本 preview 单独叠一组：
 *   - 已加载 module 的 AABB 线框（按 module hash 配色）
 *   - 每个 anchor 的小球（同色，选中 → 放大 + 垂直竖线插地）
 *   - 可达对连线（仅在 anchorStore.result 存在时）
 * 仅本 PreviewView 卸载时整组移除 + dispose，不影响 minimap。
 *
 * Anchor 只存 (worldX, worldZ)，3D 需要 Y。
 * 通过 snapAnchorPointLight 顶视 raycast 求 Y，并缓存到 anchorYCache。
 * ============================================================ */
export function usePreview({ canvasRef, containerRef, onAnchorClick }: UsePreviewOptions) {
  const { scene } = useThreeScene()
  const terrainStore = useTerrainStore()
  const modulesStore = useModulesStore()
  const anchorStore = useAnchorStore()

  let renderer: WebGLRenderer | null = null
  let camera: PerspectiveCamera | null = null
  let controls: OrbitControls | null = null
  let rafId = 0
  let resizeObserver: ResizeObserver | null = null
  let grid: GridHelper | null = null
  let hasFramedOnce = false

  // —— anchor 可视化叠加组（本 preview 私有，卸载时整组清理） ——
  const overlayGroup = new Group()
  overlayGroup.name = 'PreviewAnchorOverlay'

  // 子分组（便于按需重建）
  const boxHelpersGroup = new Group()
  const anchorBallsGroup = new Group()
  const pairLinesGroup = new Group()
  overlayGroup.add(boxHelpersGroup, anchorBallsGroup, pairLinesGroup)

  // anchor id → Mesh，用于 raycast 拾取与选中样式切换
  const anchorMeshes = new Map<string, Mesh>()
  // moduleName → Box3Helper，用于"高亮所属模块"
  const moduleBoxHelpers = new Map<string, Box3Helper>()
  // 选中模块的"光晕"外框（略放大版 Box3Helper），跟随 selectedAnchor 更新
  let highlightHaloHelper: Box3Helper | null = null
  let highlightHaloBox: Box3 | null = null
  // (x,z) → y 缓存，避免每帧 raycast
  const anchorYCache = new Map<string, number>()
  function cacheKey(x: number, z: number): string {
    return `${x.toFixed(3)}|${z.toFixed(3)}`
  }

  function moduleHueFor(name: string): number {
    let h = 0
    for (let i = 0; i < name.length; i++) {
      h = (h * 31 + name.charCodeAt(i)) | 0
    }
    return Math.abs(h) % 360
  }
  function colorFromHue(hue: number, saturation = 0.78, lightness = 0.6): Color {
    const c = new Color()
    c.setHSL(hue / 360, saturation, lightness)
    return c
  }

  function init() {
    const canvas = canvasRef()
    const container = containerRef()
    if (!canvas || !container) return

    renderer = new WebGLRenderer({ canvas, antialias: true, alpha: true })
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2))
    renderer.setClearColor(new Color(0x0a0f1c), 0)

    camera = new PerspectiveCamera(50, 1, 0.1, 5000)
    camera.position.set(60, 60, 60)
    camera.lookAt(0, 0, 0)

    controls = new OrbitControls(camera, canvas)
    controls.enableDamping = true
    controls.dampingFactor = 0.08
    controls.rotateSpeed = 0.85
    controls.addEventListener('start', onControlsStart)

    // 网格地板
    grid = new GridHelper(400, 40, 0x22d3ee, 0x1f2937)
    const gridMat = grid.material as { opacity?: number; transparent?: boolean }
    gridMat.opacity = 0.25
    gridMat.transparent = true
    scene.add(grid)

    // anchor overlay 组挂入共享 scene
    scene.add(overlayGroup)

    handleResize()
    if (typeof ResizeObserver !== 'undefined') {
      resizeObserver = new ResizeObserver(handleResize)
      resizeObserver.observe(container)
    }
    window.addEventListener('resize', handleResize)

    animate()
  }

  function handleResize() {
    const container = containerRef()
    if (!container || !renderer || !camera) return
    const w = container.clientWidth
    const h = container.clientHeight
    if (w === 0 || h === 0) return
    renderer.setSize(w, h, false)
    camera.aspect = w / h
    camera.updateProjectionMatrix()
  }

  function animate() {
    rafId = requestAnimationFrame(animate)
    if (!renderer || !camera) return
    updateFocusTween()
    controls?.update()
    updateSelectedAnchorPulse()
    renderer.render(scene, camera)
  }

  /** 根据合并 AABB 自动取景一次（首次加载时） */
  function frameToBox(box: Box3) {
    if (!camera || !controls || box.isEmpty()) return
    const center = new Vector3()
    const size = new Vector3()
    box.getCenter(center)
    box.getSize(size)
    const maxDim = Math.max(size.x, size.y, size.z) || 10
    const fitDist = maxDim / (2 * Math.tan((camera.fov * Math.PI) / 360)) * 1.6
    const dir = new Vector3(1, 0.9, 1).normalize()
    camera.position.copy(center.clone().add(dir.multiplyScalar(fitDist)))
    camera.near = Math.max(0.1, fitDist / 1000)
    camera.far = fitDist * 20
    camera.updateProjectionMatrix()
    controls.target.copy(center)
    controls.update()
  }

  // ====================================================
  //                  平滑聚焦 (focus tween)
  // ====================================================
  interface FocusTween {
    startTime: number
    duration: number
    fromPos: Vector3
    fromTarget: Vector3
    toPos: Vector3
    toTarget: Vector3
  }
  let activeTween: FocusTween | null = null

  /** 用户开始操作 → 立即中断聚焦动画 */
  function onControlsStart() {
    activeTween = null
  }

  /**
   * 平滑把相机推到"以 point 为画面中心"，保持当前观察方向与距离（仅平移）
   * 这样 selected anchor 在 3D 视口里位于正中央，且不改变现有缩放等级
   */
  function focusOnPoint(point: Vector3) {
    if (!camera || !controls) return
    const curOffset = new Vector3().subVectors(camera.position, controls.target)
    if (curOffset.lengthSq() < 1e-6) curOffset.set(1, 0.9, 1)

    const toTarget = point.clone()
    const toPos = point.clone().add(curOffset)

    activeTween = {
      startTime: performance.now(),
      duration: 520,
      fromPos: camera.position.clone(),
      fromTarget: controls.target.clone(),
      toPos,
      toTarget
    }

    const dist = curOffset.length()
    camera.near = Math.max(0.1, dist / 1000)
    camera.far = Math.max(camera.far, dist * 20)
    camera.updateProjectionMatrix()
  }

  /** 在 animate 里推进 tween */
  function updateFocusTween() {
    if (!activeTween || !camera || !controls) return
    const now = performance.now()
    const t = Math.min(1, (now - activeTween.startTime) / activeTween.duration)
    // easeInOutCubic
    const k = t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2
    camera.position.lerpVectors(activeTween.fromPos, activeTween.toPos, k)
    controls.target.lerpVectors(activeTween.fromTarget, activeTween.toTarget, k)
    if (t >= 1) activeTween = null
  }

  // ====================================================
  //              Overlay 重建（增量 / 全量）
  // ====================================================

  /** 清空一个 group 中所有子对象并释放显存 */
  function clearGroup(g: Group) {
    while (g.children.length > 0) {
      const child = g.children[0]
      g.remove(child)
      const m = child as Mesh | LineSegments | Box3Helper
      if ((m as Mesh).geometry) (m as Mesh).geometry.dispose()
      const mat = (m as Mesh).material
      if (Array.isArray(mat)) mat.forEach((mm) => mm.dispose())
      else if (mat) (mat as MeshBasicMaterial).dispose()
    }
  }

  /** 重建模块 AABB 线框（每次 modules 列表 / loaded 状态 / worldBox 变化时） */
  function rebuildModuleBoxes() {
    clearGroup(boxHelpersGroup)
    moduleBoxHelpers.clear()
    highlightHaloHelper = null
    highlightHaloBox = null
    for (const m of modulesStore.modules) {
      if (!m.loaded || m.worldBox.isEmpty()) continue
      const hue = moduleHueFor(m.name)
      const baseColor = colorFromHue(hue, 0.9, 0.65)
      const helper = new Box3Helper(m.worldBox, baseColor)
      const mat = helper.material as LineBasicMaterial
      mat.transparent = true
      mat.opacity = 0.55
      helper.userData.moduleName = m.name
      helper.userData.baseColor = baseColor.clone()
      boxHelpersGroup.add(helper)
      moduleBoxHelpers.set(m.name, helper)
    }
    applySelectedModuleStyle()
  }

  /**
   * 高亮"选中 anchor 所属模块"的 AABB 线框：
   *   - 自身：满不透明、向白色提亮 25%
   *   - 其他模块：opacity 降到 0.18，弱化背景
   *   - 额外加一个略放大的"光晕"线框包裹选中模块
   */
  function applySelectedModuleStyle() {
    const selId = anchorStore.selectedAnchorId
    const selAnchor = selId
      ? anchorStore.allAnchors.find((x: Anchor) => x.id === selId) ?? null
      : null
    const selModuleName = selAnchor?.moduleName ?? null

    for (const [name, helper] of moduleBoxHelpers) {
      const mat = helper.material as LineBasicMaterial
      const baseColor = helper.userData.baseColor as Color
      if (!selModuleName) {
        mat.color.copy(baseColor)
        mat.opacity = 0.55
      } else if (name === selModuleName) {
        mat.color.copy(baseColor).lerp(new Color(0xffffff), 0.25)
        mat.opacity = 1
      } else {
        mat.color.copy(baseColor)
        mat.opacity = 0.18
      }
    }

    // 维护"选中模块光晕"外框
    if (highlightHaloHelper) {
      boxHelpersGroup.remove(highlightHaloHelper)
      const m = highlightHaloHelper.material as LineBasicMaterial
      m.dispose()
      highlightHaloHelper = null
      highlightHaloBox = null
    }
    if (selModuleName) {
      const mod = modulesStore.modules.find((mm) => mm.name === selModuleName)
      if (mod && mod.loaded && !mod.worldBox.isEmpty()) {
        const halo = mod.worldBox.clone()
        const size = new Vector3()
        halo.getSize(size)
        // 放大 ~6%，下限 0.5 单位，避免与本体线重叠
        const pad = Math.max(0.5, Math.max(size.x, size.y, size.z) * 0.06)
        halo.expandByScalar(pad)
        const baseColor =
          (moduleBoxHelpers.get(selModuleName)?.userData.baseColor as Color) ??
          colorFromHue(moduleHueFor(selModuleName), 0.9, 0.7)
        const haloColor = baseColor.clone().lerp(new Color(0xffffff), 0.5)
        const helper = new Box3Helper(halo, haloColor)
        const mat = helper.material as LineBasicMaterial
        mat.transparent = true
        mat.opacity = 0.7
        boxHelpersGroup.add(helper)
        highlightHaloHelper = helper
        highlightHaloBox = halo
      }
    }
    void highlightHaloBox
  }

  /** 求 anchor 的 worldY（带缓存） */
  function getAnchorY(a: Anchor): number {
    const key = cacheKey(a.worldX, a.worldZ)
    const cached = anchorYCache.get(key)
    if (cached !== undefined) return cached
    const snap = snapAnchorPointLight(a.worldX, a.worldZ, {
      slopeThresholdDeg: modulesStore.slopeThresholdDeg
    })
    if (snap) {
      anchorYCache.set(key, snap.worldY)
      return snap.worldY
    }
    // 兜底：用地形合并 box 顶端 + 1，至少不会"沉到地下"
    const box = terrainStore.mergedBox
    const fallback = box && !box.isEmpty() ? box.max.y + 1 : 0
    anchorYCache.set(key, fallback)
    return fallback
  }

  /** 估计场景特征尺寸，用于 anchor 球半径 */
  function getAnchorBallRadius(): number {
    const box = terrainStore.mergedBox
    if (!box || box.isEmpty()) return 0.35
    const size = new Vector3()
    box.getSize(size)
    const maxDim = Math.max(size.x, size.z) || 10
    // 0.35% 的对角作为半径，clamp 到 [0.2, 1.5]
    return Math.min(1.5, Math.max(0.2, maxDim * 0.0035))
  }

  /** 重建 anchor 球（每次 anchors revision / module 颜色相关项变化时） */
  function rebuildAnchorBalls() {
    clearGroup(anchorBallsGroup)
    anchorMeshes.clear()

    const r = getAnchorBallRadius()
    const sphereGeo = new SphereGeometry(r, 16, 12)

    for (const a of anchorStore.allAnchors) {
      const hue = moduleHueFor(a.moduleName)
      const color = colorFromHue(hue, 0.95, 0.6)
      const mat = new MeshBasicMaterial({
        color,
        transparent: true,
        opacity: 0.95,
        depthTest: true
      })
      const mesh = new Mesh(sphereGeo, mat)
      mesh.userData.anchorId = a.id
      mesh.userData.baseColor = color.clone()
      mesh.userData.baseRadius = r
      const y = getAnchorY(a)
      mesh.position.set(a.worldX, y + r * 1.2, a.worldZ)
      anchorBallsGroup.add(mesh)
      anchorMeshes.set(a.id, mesh)
    }

    // 几何在多个 mesh 间共享，最后由 clearGroup 时 dispose（共享 → 重复释放即可，three 内部对相同已释放安全无副作用；
    // 这里改为每次都 new SphereGeometry 但 clearGroup 仅释放一次共享 → 改用 mesh.geometry 单独 ref 计数太麻烦）
    // 为简洁起见，每个 mesh 在 clearGroup 中 dispose 自己的 geometry，因此这里给每个 mesh clone 一份引用是过度优化；
    // SphereGeometry 体积小，下次 rebuild 再 new 一份即可，本实现已可接受。

    applySelectedAnchorStyle()
  }

  /** 重建可达对连线（仅 result 存在时） */
  function rebuildPairLines() {
    clearGroup(pairLinesGroup)
    const result = anchorStore.result
    if (!result) return
    const anchors = anchorStore.allAnchors
    if (anchors.length === 0) return

    const positions: number[] = []
    const colors: number[] = []
    const r = getAnchorBallRadius()

    for (const [i, j] of result.reachableAnchorPairs) {
      const a = anchors[i]
      const b = anchors[j]
      if (!a || !b) continue
      const ya = getAnchorY(a) + r * 1.2
      const yb = getAnchorY(b) + r * 1.2
      const hueA = moduleHueFor(a.moduleName)
      const hueB = moduleHueFor(b.moduleName)
      const ca = colorFromHue(hueA, 0.8, 0.65)
      const cb = colorFromHue(hueB, 0.8, 0.65)
      positions.push(a.worldX, ya, a.worldZ, b.worldX, yb, b.worldZ)
      colors.push(ca.r, ca.g, ca.b, cb.r, cb.g, cb.b)
    }
    if (positions.length === 0) return

    const geo = new BufferGeometry()
    geo.setAttribute('position', new Float32BufferAttribute(positions, 3))
    geo.setAttribute('color', new Float32BufferAttribute(colors, 3))
    const mat = new LineBasicMaterial({
      vertexColors: true,
      transparent: true,
      opacity: 0.45
    })
    const lines = new LineSegments(geo, mat)
    pairLinesGroup.add(lines)
  }

  /** 选中样式：放大 + 略偏亮 */
  function applySelectedAnchorStyle() {
    const selId = anchorStore.selectedAnchorId
    for (const [id, mesh] of anchorMeshes) {
      const baseR = mesh.userData.baseRadius as number
      const baseColor = mesh.userData.baseColor as Color
      const mat = mesh.material as MeshBasicMaterial
      if (id === selId) {
        mesh.scale.setScalar(1.6)
        mat.color.copy(baseColor).lerp(new Color(0xffffff), 0.25)
        mat.opacity = 1
      } else {
        mesh.scale.setScalar(1)
        mat.color.copy(baseColor)
        mat.opacity = 0.95
      }
      void baseR
    }
  }

  /** 选中球的脉动（在 animate 里调用） */
  function updateSelectedAnchorPulse() {
    const selId = anchorStore.selectedAnchorId
    if (!selId) return
    const mesh = anchorMeshes.get(selId)
    if (!mesh) return
    const t = (Date.now() % 1200) / 1200
    const s = 1.6 + Math.sin(t * Math.PI * 2) * 0.18
    mesh.scale.setScalar(s)
  }

  // ====================================================
  //                    点击拾取（3D）
  // ====================================================
  const raycaster = new Raycaster()
  const ndc = new Vector2()
  let pointerDownX = 0
  let pointerDownY = 0
  let pointerDownTime = 0
  const CLICK_MOVE_THRESHOLD_PX = 5
  const CLICK_TIME_THRESHOLD_MS = 350

  function onPointerDown(e: PointerEvent) {
    pointerDownX = e.clientX
    pointerDownY = e.clientY
    pointerDownTime = Date.now()
  }

  function onPointerUp(e: PointerEvent) {
    // 区分 click 与 OrbitControls 拖拽
    const dx = Math.abs(e.clientX - pointerDownX)
    const dy = Math.abs(e.clientY - pointerDownY)
    const dt = Date.now() - pointerDownTime
    if (dx > CLICK_MOVE_THRESHOLD_PX || dy > CLICK_MOVE_THRESHOLD_PX) return
    if (dt > CLICK_TIME_THRESHOLD_MS) return
    if (e.button !== 0) return
    pickAnchorAt(e.clientX, e.clientY)
  }

  function pickAnchorAt(clientX: number, clientY: number) {
    const canvas = canvasRef()
    if (!canvas || !camera) return
    const rect = canvas.getBoundingClientRect()
    ndc.x = ((clientX - rect.left) / rect.width) * 2 - 1
    ndc.y = -((clientY - rect.top) / rect.height) * 2 + 1
    raycaster.setFromCamera(ndc, camera)
    const balls = [...anchorMeshes.values()]
    if (balls.length === 0) return
    const hits = raycaster.intersectObjects(balls, false)
    if (hits.length === 0) return
    const id = hits[0].object.userData.anchorId as string | undefined
    if (!id) return
    if (onAnchorClick) {
      onAnchorClick(id)
    } else {
      // 默认行为：toggle 选中（与 2D minimap 一致）
      if (anchorStore.selectedAnchorId === id) anchorStore.selectAnchor(null)
      else anchorStore.selectAnchor(id)
    }
  }

  // ====================================================
  //                       Watchers
  // ====================================================

  // 1) terrain 首次出现 → 自动取景
  const stopTerrainWatch = watch(
    () => terrainStore.terrains.length,
    (len) => {
      if (len > 0 && !hasFramedOnce) {
        const box = terrainStore.mergedBox
        if (box) {
          frameToBox(box)
          hasFramedOnce = true
        }
      }
      if (len === 0) hasFramedOnce = false
    }
  )

  // 2) modules 列表 / loaded 状态变化 → 重建 AABB；同时坐标系/Y 缓存可能过期
  const stopModulesWatch = watch(
    () => [
      modulesStore.modules.length,
      modulesStore.loadedModuleCount,
      modulesStore.modules.map((m) => m.worldBox.min.y + m.worldBox.max.y).join(',')
    ],
    () => {
      anchorYCache.clear()
      rebuildModuleBoxes()
      rebuildAnchorBalls()
      rebuildPairLines()
    },
    { immediate: true }
  )

  // 3) anchors 增删改 → 重建球与连线
  const stopAnchorWatch = watch(
    () => [anchorStore.revision, anchorStore.allAnchors.length],
    () => {
      // 坐标可能变化（拖拽更新），清缓存重算 Y
      anchorYCache.clear()
      rebuildAnchorBalls()
      rebuildPairLines()
    }
  )

  // 4) 选中状态变化 → 样式刷新 + 聚焦到所在模块
  const stopSelectedWatch = watch(
    () => anchorStore.selectedAnchorId,
    (id) => {
      applySelectedAnchorStyle()
      applySelectedModuleStyle()
      if (!id) return
      const a = anchorStore.allAnchors.find((x: Anchor) => x.id === id)
      if (!a) return
      const y = getAnchorY(a) + getAnchorBallRadius() * 1.2
      focusOnPoint(new Vector3(a.worldX, y, a.worldZ))
    }
  )

  // 5) result 变化 → 重建连线
  const stopResultWatch = watch(
    () => anchorStore.result,
    () => rebuildPairLines()
  )

  onMounted(() => {
    init()
    const canvas = canvasRef()
    if (canvas) {
      canvas.addEventListener('pointerdown', onPointerDown)
      canvas.addEventListener('pointerup', onPointerUp)
    }
  })

  onBeforeUnmount(() => {
    stopTerrainWatch()
    stopModulesWatch()
    stopAnchorWatch()
    stopSelectedWatch()
    stopResultWatch()

    const canvas = canvasRef()
    if (canvas) {
      canvas.removeEventListener('pointerdown', onPointerDown)
      canvas.removeEventListener('pointerup', onPointerUp)
    }

    cancelAnimationFrame(rafId)
    window.removeEventListener('resize', handleResize)
    resizeObserver?.disconnect()
    controls?.removeEventListener('start', onControlsStart)
    controls?.dispose()
    renderer?.dispose()

    clearGroup(boxHelpersGroup)
    clearGroup(anchorBallsGroup)
    clearGroup(pairLinesGroup)
    scene.remove(overlayGroup)
    if (grid) scene.remove(grid)
  })

  return {
    frameToBox: (box: Box3) => frameToBox(box)
  }
}
