<script setup lang="ts">
import { onBeforeUnmount, ref } from 'vue'
import PreviewView from './PreviewView.vue'
import UploadPanel from './UploadPanel.vue'
import ManifestPanel from './ManifestPanel.vue'
import AnchorMinimap from './AnchorMinimap.vue'
import AnchorPanel from './AnchorPanel.vue'
import { useModulesStore } from '../stores/modules'

/**
 * AnchorView：Anchor 推导独立视图（精简版，仅保留 anchor 推导相关功能）。
 * - 左侧大区域：AnchorMinimap（2D 俯视图 + anchor 选中/添加/拖拽）
 * - 右侧侧边栏：UploadPanel / ManifestPanel / AnchorPanel + Anchor 算法说明
 */

const modulesStore = useModulesStore()

const SIDEBAR_KEY = 'gtm.sidebar.width'
const MIN_W = 280
const MAX_W = 720
const DEFAULT_W = 360

function loadInitialWidth(): number {
  const raw = localStorage.getItem(SIDEBAR_KEY)
  const n = raw ? Number(raw) : NaN
  if (!Number.isFinite(n)) return DEFAULT_W
  return Math.min(MAX_W, Math.max(MIN_W, n))
}

const sidebarWidth = ref<number>(loadInitialWidth())
const dragging = ref(false)

function clampWidth(w: number): number {
  const vw = window.innerWidth
  const dynMax = Math.max(MIN_W, Math.min(MAX_W, vw - 360))
  return Math.min(dynMax, Math.max(MIN_W, w))
}

function onDragMove(e: MouseEvent) {
  if (!dragging.value) return
  const next = clampWidth(window.innerWidth - e.clientX - 12)
  sidebarWidth.value = next
}

function endDrag() {
  if (!dragging.value) return
  dragging.value = false
  document.body.style.cursor = ''
  document.body.style.userSelect = ''
  window.removeEventListener('mousemove', onDragMove)
  window.removeEventListener('mouseup', endDrag)
  try { localStorage.setItem(SIDEBAR_KEY, String(Math.round(sidebarWidth.value))) } catch { /* ignore */ }
}

function startDrag(e: MouseEvent) {
  e.preventDefault()
  dragging.value = true
  document.body.style.cursor = 'col-resize'
  document.body.style.userSelect = 'none'
  window.addEventListener('mousemove', onDragMove)
  window.addEventListener('mouseup', endDrag)
}

onBeforeUnmount(() => {
  window.removeEventListener('mousemove', onDragMove)
  window.removeEventListener('mouseup', endDrag)
})
</script>

<template>
  <main class="flex-1 min-h-0 flex p-3 gap-1">
    <!-- 左侧大区域：Anchor Minimap -->
    <section class="flex-1 min-w-0 overflow-y-auto scrollbar-thin pr-1">
      <AnchorMinimap />
    </section>

    <!-- 拖拽分隔条 -->
    <div
      class="group relative shrink-0 w-2 cursor-col-resize flex items-center justify-center"
      :class="dragging ? 'bg-emerald-400/20' : 'hover:bg-white/5'"
      title="拖动调整侧边栏宽度"
      role="separator"
      aria-orientation="vertical"
      @mousedown="startDrag"
    >
      <div
        class="w-[2px] h-10 rounded-full transition-colors"
        :class="dragging ? 'bg-emerald-300' : 'bg-white/15 group-hover:bg-emerald-400/70'"
      />
    </div>

    <!-- 右侧浮层卡片 -->
    <aside
      class="shrink-0 flex flex-col gap-3 overflow-y-auto scrollbar-thin pr-1 pl-2"
      :style="{ width: sidebarWidth + 'px' }"
    >
      <UploadPanel />
      <ManifestPanel />
      <!-- 3D 预览（侧边栏小窗：固定 16:10 比例） -->
      <div class="shrink-0 w-full aspect-[16/10]">
        <PreviewView />
      </div>
      <AnchorPanel v-if="modulesStore.hasManifest" />

      <!-- 算法说明卡片：Anchor 专版 -->
      <div class="glass-card p-3 text-[11px] leading-relaxed text-slate-300 space-y-2">
        <div class="flex items-center gap-2 text-emerald-300 font-semibold">
          <span class="w-1.5 h-1.5 rounded-full bg-emerald-400" />
          Anchor 推导说明
        </div>
        <p class="text-slate-400">
          为每个 module 标注 ≥1 个可达点（anchor），通过 anchor 之间的连通性反推 module 邻接：
        </p>
        <div class="space-y-1.5">
          <div class="rounded border border-fuchsia-400/20 bg-fuchsia-400/[0.04] p-2">
            <div class="text-fuchsia-300 font-semibold mb-0.5">① 局部 A* · 快（默认）</div>
            <ol class="list-decimal pl-4 space-y-0.5 text-slate-400 text-[10.5px]">
              <li>raycast 顶视吸附生成默认 anchor（免全图栅格化）</li>
              <li>module 对 XZ 间距阈值剪枝出候选对</li>
              <li>仅对候选对的局部矩形做栅格化 + 单对 A*</li>
              <li>地图越稀疏越快，输出结构与全图方案 100% 兼容</li>
            </ol>
          </div>
          <div class="rounded border border-cyan-400/20 bg-cyan-400/[0.04] p-2">
            <div class="text-cyan-300 font-semibold mb-0.5">② 全图扩散 · 精（对照）</div>
            <ol class="list-decimal pl-4 space-y-0.5 text-slate-400 text-[10.5px]">
              <li>全图栅格化 + passEdge 段落悬崖检测</li>
              <li>单次多源 Dijkstra → anchor 两两可达</li>
              <li>语义最严格，可作为局部方案的对照</li>
            </ol>
          </div>
        </div>
        <p class="text-slate-500 text-[10px] pt-1 border-t border-white/5">
          <span class="text-emerald-300">邻接判定：</span>
          "A 任一 anchor 能到 B 任一 anchor" ⇒ A↔B 邻接，会保留可达传递性
          （A→C 必经 B 时 A-C 也算邻接）。
        </p>
      </div>
    </aside>

    <div v-if="dragging" class="fixed inset-0 z-50 cursor-col-resize" />
  </main>
</template>
