<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useModulesStore } from '../stores/modules'
import { useAnchorStore } from '../stores/anchors'
import type { MinimapViewState, ModuleRuntime } from '../types/modules'

/**
 * Anchor 推导专用 overlay（基于 minimap canvas 之上的 2D 图层）。
 *
 * 图层顺序（从下到上）：
 *   1) 模块矩形（loaded module 的 worldBox）
 *   2) Anchor 可达对连线（仅在 anchorStore.result 存在时）
 *   3) 添加模式：目标 module 的高亮 worldBox（虚线描边 + 半透明填色）
 *   4) Anchor 圆点（按 module hash 配色，selected/hovered 放大 + 发光环）
 *   5) 模块名标签
 */

const props = defineProps<{
  viewState: MinimapViewState
  containerRef: () => HTMLElement | null
}>()

const modulesStore = useModulesStore()
const anchorStore = useAnchorStore()
const overlayRef = ref<HTMLCanvasElement | null>(null)

let rafId = 0
let needsRedraw = true
function requestRedraw() { needsRedraw = true }

function loop() {
  rafId = requestAnimationFrame(loop)
  if (!needsRedraw) return
  draw()
  needsRedraw = false
}

function moduleHueFor(name: string): number {
  let h = 0
  for (let i = 0; i < name.length; i++) {
    h = (h * 31 + name.charCodeAt(i)) | 0
  }
  return Math.abs(h) % 360
}

function draw() {
  const canvas = overlayRef.value
  const container = props.containerRef()
  if (!canvas || !container) return
  const w = container.clientWidth
  const h = container.clientHeight
  if (w === 0 || h === 0) return

  const dpr = Math.min(window.devicePixelRatio, 2)
  if (canvas.width !== Math.round(w * dpr) || canvas.height !== Math.round(h * dpr)) {
    canvas.width = Math.round(w * dpr)
    canvas.height = Math.round(h * dpr)
    canvas.style.width = `${w}px`
    canvas.style.height = `${h}px`
  }
  const ctx = canvas.getContext('2d')
  if (!ctx) return
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
  ctx.clearRect(0, 0, w, h)

  if (!modulesStore.hasManifest) return

  const vs = props.viewState
  const cx = vs.baseCenterX + vs.userOffsetX
  const cz = vs.baseCenterZ + vs.userOffsetZ
  const halfW = vs.halfW
  const halfH = vs.halfH
  if (halfW <= 0 || halfH <= 0) return

  const worldToScreen = (wx: number, wz: number) => {
    const u = (wx - cx) / (halfW * 2) + 0.5
    const v = (wz - cz) / (halfH * 2) + 0.5
    return { x: u * w, y: v * h }
  }

  // ---------- 图层 1：模块矩形 ----------
  for (const m of modulesStore.modules) {
    if (!m.loaded) continue
    drawModuleRect(ctx, m, worldToScreen)
  }

  // ---------- 图层 2/3/4：anchor 相关 ----------
  drawAnchors(ctx, worldToScreen)

  // ---------- 图层 5：模块名 ----------
  ctx.font = '10px Inter, system-ui, sans-serif'
  ctx.textAlign = 'left'
  ctx.textBaseline = 'top'
  ctx.fillStyle = 'rgba(226,232,240,0.75)'
  ctx.shadowColor = 'rgba(0,0,0,0.6)'
  ctx.shadowBlur = 2
  for (const m of modulesStore.modules) {
    if (!m.loaded) continue
    const p = worldToScreen(m.worldBox.min.x + 1, m.worldBox.min.z + 1)
    ctx.fillText(m.name, p.x, p.y)
  }
  ctx.shadowBlur = 0

  // 选中态有动画 → 持续重绘
  if (anchorStore.selectedAnchorId) needsRedraw = true
}

function drawModuleRect(
  ctx: CanvasRenderingContext2D,
  m: ModuleRuntime,
  worldToScreen: (x: number, z: number) => { x: number; y: number }
) {
  if (m.worldBox.isEmpty()) return
  const p1 = worldToScreen(m.worldBox.min.x, m.worldBox.min.z)
  const p2 = worldToScreen(m.worldBox.max.x, m.worldBox.max.z)
  const x = Math.min(p1.x, p2.x)
  const y = Math.min(p1.y, p2.y)
  const w = Math.abs(p2.x - p1.x)
  const h = Math.abs(p2.y - p1.y)

  ctx.fillStyle = 'rgba(56,189,248,0.10)'
  ctx.strokeStyle = 'rgba(56,189,248,0.55)'
  ctx.lineWidth = 1
  ctx.fillRect(x, y, w, h)
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1)
}

function drawAnchors(
  ctx: CanvasRenderingContext2D,
  worldToScreen: (x: number, z: number) => { x: number; y: number }
) {
  const anchors = anchorStore.allAnchors
  const result = anchorStore.result

  // —— 添加模式：高亮目标 module 的 worldBox ——
  const addName = anchorStore.addModeModuleName
  if (addName) {
    const m = modulesStore.modules.find((mm) => mm.name === addName && mm.loaded)
    if (m && !m.worldBox.isEmpty()) {
      const p1 = worldToScreen(m.worldBox.min.x, m.worldBox.min.z)
      const p2 = worldToScreen(m.worldBox.max.x, m.worldBox.max.z)
      const x = Math.min(p1.x, p2.x)
      const y = Math.min(p1.y, p2.y)
      const w = Math.abs(p2.x - p1.x)
      const h = Math.abs(p2.y - p1.y)
      const hue = moduleHueFor(addName)
      ctx.save()
      ctx.setLineDash([5, 4])
      ctx.fillStyle = `hsla(${hue},85%,60%,0.10)`
      ctx.fillRect(x, y, w, h)
      ctx.strokeStyle = `hsla(${hue},85%,65%,0.95)`
      ctx.lineWidth = 2
      ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1)
      ctx.restore()
    }
  }

  // —— 选中 anchor：高亮其所属 module 的 worldBox（金色描边） + 连线到 box 中心 ——
  // 用于诊断"anchor 圆点位置 vs 它名义所属 module 框位置"是否对齐
  const selId = anchorStore.selectedAnchorId
  if (selId) {
    const sel = anchorStore.getById(selId)
    if (sel) {
      const m = modulesStore.modules.find((mm) => mm.name === sel.moduleName && mm.loaded)
      if (m && !m.worldBox.isEmpty()) {
        const p1 = worldToScreen(m.worldBox.min.x, m.worldBox.min.z)
        const p2 = worldToScreen(m.worldBox.max.x, m.worldBox.max.z)
        const x = Math.min(p1.x, p2.x)
        const y = Math.min(p1.y, p2.y)
        const w = Math.abs(p2.x - p1.x)
        const h = Math.abs(p2.y - p1.y)
        ctx.save()
        // 金色高亮填色 + 描边
        ctx.fillStyle = 'rgba(251,191,36,0.10)'
        ctx.fillRect(x, y, w, h)
        ctx.strokeStyle = 'rgba(251,191,36,0.95)'
        ctx.lineWidth = 2
        ctx.setLineDash([6, 4])
        ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1)
        // 从 anchor 圆点到 box 中心画一条短线（视觉上一目了然是否同一区域）
        const pa = worldToScreen(sel.worldX, sel.worldZ)
        const pc = worldToScreen(
          (m.worldBox.min.x + m.worldBox.max.x) / 2,
          (m.worldBox.min.z + m.worldBox.max.z) / 2
        )
        ctx.setLineDash([])
        ctx.strokeStyle = 'rgba(251,191,36,0.75)'
        ctx.lineWidth = 1
        ctx.beginPath()
        ctx.moveTo(pa.x, pa.y)
        ctx.lineTo(pc.x, pc.y)
        ctx.stroke()
        // box 中心打十字
        ctx.beginPath()
        ctx.moveTo(pc.x - 4, pc.y)
        ctx.lineTo(pc.x + 4, pc.y)
        ctx.moveTo(pc.x, pc.y - 4)
        ctx.lineTo(pc.x, pc.y + 4)
        ctx.stroke()
        ctx.restore()
      }
    }
  }

  if (anchors.length === 0) return

  // —— 可达对连线（在 anchor 圆点下方） ——
  if (result) {
    ctx.save()
    ctx.lineWidth = 1
    for (const [i, j] of result.reachableAnchorPairs) {
      const a = anchors[i]
      const b = anchors[j]
      if (!a || !b) continue
      const pa = worldToScreen(a.worldX, a.worldZ)
      const pb = worldToScreen(b.worldX, b.worldZ)
      const hueA = moduleHueFor(a.moduleName)
      const hueB = moduleHueFor(b.moduleName)
      const hue = (hueA + hueB) / 2
      ctx.strokeStyle = `hsla(${hue},80%,65%,0.35)`
      ctx.beginPath()
      ctx.moveTo(pa.x, pa.y)
      ctx.lineTo(pb.x, pb.y)
      ctx.stroke()
    }
    ctx.restore()
  }

  // —— anchor 圆点 ——
  const selectedId = anchorStore.selectedAnchorId
  const hoveredId = anchorStore.hoveredAnchorId
  for (const a of anchors) {
    const p = worldToScreen(a.worldX, a.worldZ)
    const hue = moduleHueFor(a.moduleName)
    const isSelected = selectedId === a.id
    const isHovered = hoveredId === a.id
    const r = isSelected ? 7 : isHovered ? 6 : 5

    // 选中发光环
    if (isSelected) {
      const t = (Date.now() % 1400) / 1400
      const ringR = r + 4 + t * 10
      ctx.beginPath()
      ctx.arc(p.x, p.y, ringR, 0, Math.PI * 2)
      ctx.strokeStyle = `hsla(${hue},90%,70%,${(1 - t) * 0.85})`
      ctx.lineWidth = 2
      ctx.stroke()
    }

    // 主圆点
    ctx.beginPath()
    ctx.arc(p.x, p.y, r, 0, Math.PI * 2)
    ctx.fillStyle = `hsla(${hue},85%,60%,0.95)`
    ctx.fill()
    ctx.strokeStyle = 'rgba(255,255,255,0.9)'
    ctx.lineWidth = 1.5
    ctx.stroke()

    // 默认 anchor 加内圈圆环
    if (a.isDefault) {
      ctx.beginPath()
      ctx.arc(p.x, p.y, r - 2.5, 0, Math.PI * 2)
      ctx.strokeStyle = 'rgba(255,255,255,0.65)'
      ctx.lineWidth = 1
      ctx.stroke()
    }
  }
}

watch(
  () => [
    props.viewState.userZoom,
    props.viewState.userOffsetX,
    props.viewState.userOffsetZ,
    props.viewState.halfW,
    props.viewState.halfH,
    props.viewState.baseCenterX,
    props.viewState.baseCenterZ,
    modulesStore.modules.length,
    anchorStore.overlayDirty,
    anchorStore.revision,
    anchorStore.selectedAnchorId,
    anchorStore.hoveredAnchorId,
    anchorStore.addModeModuleName,
    anchorStore.result
  ],
  () => requestRedraw(),
  { deep: false }
)

onMounted(() => { rafId = requestAnimationFrame(loop) })
onBeforeUnmount(() => cancelAnimationFrame(rafId))
</script>

<template>
  <canvas
    ref="overlayRef"
    class="absolute inset-0 pointer-events-none"
  />
</template>
