<script setup lang="ts">
import { onBeforeUnmount, ref, watch } from 'vue'
import { Download, Maximize2, Map as MapIcon, Crosshair } from 'lucide-vue-next'
import { useMinimap } from '../composables/useMinimap'
import { useTerrainStore } from '../stores/terrain'
import { useModulesStore } from '../stores/modules'
import { useAnchorStore } from '../stores/anchors'
import { snapAnchorPointLight } from '../composables/useAnchorSnap'
import type { MinimapResolution } from '../types'
import AnchorOverlay from './AnchorOverlay.vue'

/**
 * Anchor 推导专用 minimap：
 *   - 共享 useThreeScene 单例渲染地形 mesh
 *   - 点击：命中已有 anchor → 选中/取消；处于添加模式 → 通过 raycast 吸附添加；空地点击不再写起点
 *   - 选中 anchor 后可拖拽：实时 raycast 吸附，更新坐标
 *
 * 已切换到 raycast 吸附路径（snapAnchorPointLight），不再依赖全图 walkableMap。
 */

/** 命中半径（米）：点中已有 anchor / 启动拖拽都用此距离判定 */
const HIT_RADIUS_M = 1.5

const containerRef = ref<HTMLDivElement | null>(null)
const canvasRef = ref<HTMLCanvasElement | null>(null)
const store = useTerrainStore()
const modulesStore = useModulesStore()
const anchorStore = useAnchorStore()

/**
 * minimap 点击分发（优先级从高到低）：
 *   1) 命中已有 anchor → 选中/取消选中
 *   2) 处于"添加 anchor 模式" → raycast 吸附后追加到目标 module
 *   3) 默认：忽略（anchor 视图不再支持空地点击设置起点）
 */
function onMinimapPick(worldX: number, worldZ: number) {
  // 1) 命中已有 anchor？
  const hitR2 = HIT_RADIUS_M * HIT_RADIUS_M
  let hitAnchorId: string | null = null
  let hitBestD2 = Infinity
  for (const a of anchorStore.allAnchors) {
    const dx = a.worldX - worldX
    const dz = a.worldZ - worldZ
    const d2 = dx * dx + dz * dz
    if (d2 < hitR2 && d2 < hitBestD2) {
      hitBestD2 = d2
      hitAnchorId = a.id
    }
  }
  if (hitAnchorId) {
    if (anchorStore.selectedAnchorId === hitAnchorId) {
      anchorStore.selectAnchor(null)
    } else {
      anchorStore.selectAnchor(hitAnchorId)
    }
    return
  }

  // 2) 添加 anchor 模式：raycast 吸附
  const addModule = anchorStore.addModeModuleName
  if (addModule) {
    const lite = snapAnchorPointLight(worldX, worldZ, {
      slopeThresholdDeg: modulesStore.slopeThresholdDeg
    })
    if (!lite) {
      console.warn('[Anchor] 点击位置上方无可走面（射线无命中 / 倒挂面 / 超出坡度阈值）')
      return
    }
    const seq = anchorStore.nextSeq(addModule)
    anchorStore.pushAnchor({
      id: `${addModule}#${seq}`,
      moduleName: addModule,
      worldX: lite.worldX,
      worldZ: lite.worldZ,
      cellIdx: -1,
      isDefault: false
    })
    anchorStore.leaveAddMode()
  }
}

const { resetView, exportPNG, viewState, screenToWorld } = useMinimap({
  canvasRef: () => canvasRef.value,
  containerRef: () => containerRef.value,
  // 总是开启 click 派发，让 anchor 选中/添加在任意时刻都能工作
  isPickModeOn: () => true,
  onPick: onMinimapPick
})

/* ============================================================
 * 选中 anchor 的拖拽移动
 * ------------------------------------------------------------
 * 触发条件：pointerdown 时按下点距离"已选中 anchor"在 hitR 内
 *           → 进入 drag 模式，stopPropagation 阻止 useMinimap 平移地图
 * 拖拽过程：实时把新位置吸附到 walkable 并 anchorStore.updateAnchorPosition
 * 结束：    pointerup 释放 capture；并阻止后续 click 派发
 * ============================================================ */
let isDraggingAnchor = false
let suppressNextClick = false
let dragAnchorId: string | null = null
let dragPointerId = -1

function findAnchorAtClient(clientX: number, clientY: number): string | null {
  const w = screenToWorld(clientX, clientY)
  if (!w) return null
  const r2 = HIT_RADIUS_M * HIT_RADIUS_M
  const sel = anchorStore.selectedAnchorId
  if (sel) {
    const a = anchorStore.getById(sel)
    if (a) {
      const dx = a.worldX - w.x, dz = a.worldZ - w.z
      if (dx * dx + dz * dz < r2) return sel
    }
  }
  return null
}

function snapForMove(worldX: number, worldZ: number): { x: number; z: number; cellIdx: number } | null {
  const lite = snapAnchorPointLight(worldX, worldZ, {
    slopeThresholdDeg: modulesStore.slopeThresholdDeg
  })
  if (!lite) return null
  return { x: lite.worldX, z: lite.worldZ, cellIdx: -1 }
}

function onAnchorPointerDown(e: PointerEvent) {
  if (e.button !== 0) return
  // 添加模式优先：让原 onPick 流程负责"点击空地添加"
  if (anchorStore.addModeModuleName) return
  const id = findAnchorAtClient(e.clientX, e.clientY)
  if (!id) return
  e.stopPropagation()
  e.preventDefault()
  isDraggingAnchor = true
  suppressNextClick = false
  dragAnchorId = id
  dragPointerId = e.pointerId
  const canvas = canvasRef.value
  canvas?.setPointerCapture?.(e.pointerId)
  document.body.style.cursor = 'grabbing'
}

function onAnchorPointerMove(e: PointerEvent) {
  if (!isDraggingAnchor || !dragAnchorId) return
  if (e.pointerId !== dragPointerId) return
  const w = screenToWorld(e.clientX, e.clientY)
  if (!w) return
  const snap = snapForMove(w.x, w.z)
  if (!snap) return
  suppressNextClick = true
  anchorStore.updateAnchorPosition(dragAnchorId, snap.x, snap.z, snap.cellIdx)
}

function onAnchorPointerUp(e: PointerEvent) {
  if (!isDraggingAnchor) return
  if (e.pointerId !== dragPointerId) return
  const canvas = canvasRef.value
  canvas?.releasePointerCapture?.(e.pointerId)
  isDraggingAnchor = false
  dragAnchorId = null
  dragPointerId = -1
  document.body.style.cursor = ''
  if (suppressNextClick) {
    e.stopPropagation()
  }
}

const stopAttachWatch = watch(canvasRef, (canvas, _old, onCleanup) => {
  if (!canvas) return
  canvas.addEventListener('pointerdown', onAnchorPointerDown, true)
  window.addEventListener('pointermove', onAnchorPointerMove, true)
  window.addEventListener('pointerup', onAnchorPointerUp, true)
  onCleanup(() => {
    canvas.removeEventListener('pointerdown', onAnchorPointerDown, true)
    window.removeEventListener('pointermove', onAnchorPointerMove, true)
    window.removeEventListener('pointerup', onAnchorPointerUp, true)
  })
}, { immediate: true })

onBeforeUnmount(() => {
  stopAttachWatch()
})

const resolutions: MinimapResolution[] = [256, 512, 1024]
const exported = ref(false)

function onExport() {
  exportPNG(`anchor-minimap-${Date.now()}.png`)
  exported.value = true
  window.setTimeout(() => (exported.value = false), 1400)
}

const isCanvasEmpty = () => store.isEmpty && modulesStore.loadedModuleCount === 0
</script>

<template>
  <div class="glass-card p-3 flex flex-col gap-3 animate-fade-in">
    <!-- 标题栏 -->
    <div class="flex items-center justify-between px-1">
      <div class="flex items-center gap-2">
        <MapIcon class="w-4 h-4 text-emerald-400" />
        <span class="text-sm font-semibold tracking-wide">Anchor Minimap</span>
        <span v-if="!store.isEmpty" class="chip">
          {{ store.count }} {{ store.count > 1 ? 'tiles' : 'tile' }}
        </span>
        <span
          v-if="modulesStore.loadedModuleCount > 0"
          class="chip text-emerald-300/80 border-emerald-400/30"
        >
          {{ modulesStore.loadedModuleCount }} modules
        </span>
      </div>
      <div class="flex items-center gap-1">
        <button
          v-for="r in resolutions"
          :key="r"
          class="px-2 py-0.5 text-[11px] rounded border transition-colors cursor-pointer"
          :class="
            store.minimapResolution === r
              ? 'bg-emerald-400/15 border-emerald-400/60 text-emerald-300'
              : 'border-white/10 text-slate-400 hover:text-slate-200 hover:border-white/20'
          "
          @click="store.setResolution(r)"
        >
          {{ r }}
        </button>
      </div>
    </div>

    <!-- 选中 anchor 拖动提示 -->
    <div
      v-if="anchorStore.selectedAnchorId"
      class="flex items-center gap-2 px-3 py-1.5 rounded-md text-[11px] bg-emerald-400/10 border border-emerald-400/30 text-emerald-300"
    >
      <Crosshair class="w-3.5 h-3.5 shrink-0" />
      <span>
        已选中 <span class="font-mono text-emerald-200">{{ anchorStore.selectedAnchorId }}</span>
        · 按住可拖动到新位置（实时 raycast 吸附地形）
      </span>
    </div>

    <!-- 小地图画布 -->
    <div
      ref="containerRef"
      class="relative aspect-square w-full rounded-lg overflow-hidden bg-black/40 border border-emerald-400/20"
      :style="{ boxShadow: 'inset 0 0 16px rgba(52,211,153,0.15)' }"
    >
      <canvas
        ref="canvasRef"
        class="block mx-auto select-none"
        :class="
          isCanvasEmpty()
            ? 'opacity-0'
            : anchorStore.addModeModuleName
              ? 'cursor-crosshair'
              : 'cursor-grab active:cursor-grabbing'
        "
      />

      <AnchorOverlay :view-state="viewState" :container-ref="() => containerRef" />

      <div
        v-if="anchorStore.isSegmentPreparing"
        class="absolute inset-0 flex flex-col items-center justify-center bg-black/40 backdrop-blur-sm"
      >
        <div class="text-xs text-amber-300 font-mono mb-2">
          悬崖检测预计算 {{ (anchorStore.segmentPrepareProgress * 100).toFixed(0) }}%
        </div>
        <div class="w-2/3 h-1 rounded-full bg-white/10 overflow-hidden">
          <div
            class="h-full bg-gradient-to-r from-amber-400 to-rose-500 transition-all"
            :style="{ width: `${anchorStore.segmentPrepareProgress * 100}%` }"
          />
        </div>
      </div>

      <div
        v-if="isCanvasEmpty()"
        class="absolute inset-0 flex flex-col items-center justify-center text-slate-500 pointer-events-none"
      >
        <MapIcon class="w-8 h-8 mb-2 opacity-50" :stroke-width="1.4" />
        <div class="text-xs">上传 GLB 后自动生成</div>
      </div>

      <div
        v-if="!isCanvasEmpty()"
        class="absolute bottom-1.5 right-2 text-[10px] text-emerald-300/80 font-mono tracking-wider pointer-events-none"
      >
        ANCHOR · GLB-COLLISION
      </div>
    </div>

    <!-- 操作栏：基础 -->
    <div class="flex items-center gap-2">
      <button
        class="btn-cyan flex-1 justify-center"
        :disabled="isCanvasEmpty()"
        :class="{ 'opacity-50 cursor-not-allowed hover:translate-y-0 hover:border-white/10 hover:text-slate-100 hover:shadow-none': isCanvasEmpty() }"
        @click="resetView"
      >
        <Maximize2 class="w-3.5 h-3.5" /> 重置视图
      </button>
      <button
        class="btn-cyan flex-1 justify-center"
        :disabled="isCanvasEmpty()"
        :class="{ 'opacity-50 cursor-not-allowed hover:translate-y-0 hover:border-white/10 hover:text-slate-100 hover:shadow-none': isCanvasEmpty() }"
        @click="onExport"
      >
        <Download class="w-3.5 h-3.5" />
        {{ exported ? '已导出' : '导出 PNG' }}
      </button>
    </div>
  </div>
</template>
