import type { ModuleRuntime } from '../types/modules'

/**
 * ============================================================
 * 候选 module pair 生成（方案 D 配套）
 * ============================================================
 *
 * 一次 N² AABB 测试，把"XZ 投影后接触/相邻"的 module 对挑出来，
 * 后续只在这些对的局部矩形里栅格化 + A*。
 *
 * 剪枝策略：把每个 module 的 worldBox 在 XZ 方向各膨胀 padding/2，
 * 两 module 膨胀后矩形相交即视为候选对。
 *
 * 等价表述：原始矩形之间的 XZ "最近间距 ≤ padding" → 候选。
 *
 * 为什么这是合理的剪枝：
 *   方案 D 的可达性等价于"在 union(A.box, B.box) 局部栅格上 anchor 能跑通"。
 *   若两 module 的 XZ 间距远大于 padding（一般 ≥2m），它们之间不可能存在
 *   一条"宽度 < padding 的走廊"使 A→B 物理可达 —— 此类对默认不可达，
 *   不参与局部 A*，从而把候选对数从 N(N-1)/2 降到 O(N) 量级（地图密度相关）。
 *
 * padding 建议：
 *   - 太小（<0.5m）：紧贴但 worldBox 有 0.x 米薄缝的对会漏判
 *   - 太大（>5m）：候选对数迅速膨胀，丧失剪枝收益
 *   - 默认 2.0m，UI 暴露滑杆（0~10m）
 * ============================================================
 */

/** XZ 平面矩形（min/max） */
export interface BoxXZ {
  minX: number
  maxX: number
  minZ: number
  maxZ: number
}

export interface CandidatePair {
  modA: ModuleRuntime
  modB: ModuleRuntime
  /** A、B worldBox XZ 投影的并集（不含 padding，供局部栅格化使用） */
  unionBoxXZ: BoxXZ
  /** A、B XZ 投影间距（米）；接触/重叠时为 0 */
  xzGap: number
}

export interface BuildCandidatePairsResult {
  pairs: CandidatePair[]
  stats: {
    moduleCount: number
    totalPossible: number
    candidateCount: number
    elapsedMs: number
    padding: number
  }
}

/** ModuleRuntime.worldBox → BoxXZ */
function moduleBoxXZ(m: ModuleRuntime): BoxXZ {
  return {
    minX: m.worldBox.min.x,
    maxX: m.worldBox.max.x,
    minZ: m.worldBox.min.z,
    maxZ: m.worldBox.max.z
  }
}

/**
 * 两矩形 XZ 间距（米）。
 * - 相交/包含：返回 0
 * - 仅在某一轴分离：返回该轴间距
 * - 两轴都分离：返回欧氏距离
 */
function xzGap(a: BoxXZ, b: BoxXZ): number {
  const dx = b.minX > a.maxX ? b.minX - a.maxX : a.minX > b.maxX ? a.minX - b.maxX : 0
  const dz = b.minZ > a.maxZ ? b.minZ - a.maxZ : a.minZ > b.maxZ ? a.minZ - b.maxZ : 0
  if (dx === 0 && dz === 0) return 0
  return Math.sqrt(dx * dx + dz * dz)
}

/** 两 BoxXZ 的并集 */
function unionXZ(a: BoxXZ, b: BoxXZ): BoxXZ {
  return {
    minX: Math.min(a.minX, b.minX),
    maxX: Math.max(a.maxX, b.maxX),
    minZ: Math.min(a.minZ, b.minZ),
    maxZ: Math.max(a.maxZ, b.maxZ)
  }
}

/**
 * 计算候选 module pair 列表。
 *
 * @param modules  modules 数组（仅 loaded=true 且 worldBox 非空 的会参与）
 * @param padding  XZ 接触判定阈值（米）；间距 ≤ padding 视为候选
 */
export function buildCandidateModulePairs(
  modules: ModuleRuntime[],
  padding = 2.0
): BuildCandidatePairsResult {
  const t0 = performance.now()
  // 仅取有效 module
  const valid = modules.filter((m) => m.loaded && !m.worldBox.isEmpty())
  const N = valid.length
  const totalPossible = (N * (N - 1)) / 2
  const pairs: CandidatePair[] = []

  // 预算 XZ 投影，避免循环内重复读取
  const boxes: BoxXZ[] = valid.map(moduleBoxXZ)

  for (let i = 0; i < N; i++) {
    for (let j = i + 1; j < N; j++) {
      const gap = xzGap(boxes[i], boxes[j])
      if (gap <= padding) {
        pairs.push({
          modA: valid[i],
          modB: valid[j],
          unionBoxXZ: unionXZ(boxes[i], boxes[j]),
          xzGap: gap
        })
      }
    }
  }

  const elapsedMs = performance.now() - t0
  return {
    pairs,
    stats: {
      moduleCount: N,
      totalPossible,
      candidateCount: pairs.length,
      elapsedMs,
      padding
    }
  }
}

/**
 * 膨胀 BoxXZ：四个方向各扩 padding 米，用于局部栅格化范围。
 *
 * 为什么栅格化范围要再膨胀一圈：
 *   anchor 经过局部 walkable 校验后，若落到栅格化矩形的边界 cell 上，
 *   A* 4 邻接扩展会向外越界 —— 在边界附近多一圈 padding 能避免起点
 *   或必经路径被截断。
 */
export function expandBoxXZ(box: BoxXZ, padding: number): BoxXZ {
  return {
    minX: box.minX - padding,
    maxX: box.maxX + padding,
    minZ: box.minZ - padding,
    maxZ: box.maxZ + padding
  }
}
